(362291,40255,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Un homme a installé l''isolation, et l''autre ...'::text,'aussi'::text,'était aussi'::text,'non plus'::text,'Un homme a installé l''isolation, et l''autre aussi.'::text),
(362294,40255,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Adamlardan biri yalıtımı taktı, diğeri de ...'::text,'taktı'::text,'öyleydi'::text,'takmadı'::text,'Adamlardan biri yalıtımı taktı, diğeri de taktı.'::text),
(362295,40255,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Az egyik férfi beszerelte a szigetelést, és a másik ...'::text,'is'::text,'is volt'::text,'sem'::text,'Az egyik férfi beszerelte a szigetelést, és a másik is.'::text),
(362298,40256,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bis nächstes Wochenende ... die beiden Männer eine Dusche und eine Küche in den Van eingebaut haben.'::text,'werden'::text,'werden'::text,'werden'::text,'Bis nächstes Wochenende werden die beiden Männer eine Dusche und eine Küche in den Van eingebaut haben.'::text),
(362302,40256,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'До наступних вихідних двоє чоловіків ... у фургон душ і кухню.'::text,'встановлять'::text,'встановлять'::text,'встановлюватимуть'::text,'До наступних вихідних двоє чоловіків встановлять у фургон душ і кухню.'::text),
(362301,40256,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Para el próximo fin de semana, los dos hombres ... una ducha y una cocina en la furgoneta.'::text,'habrán instalado'::text,'instalarán'::text,'estarán instalando'::text,'Para el próximo fin de semana, los dos hombres habrán instalado una ducha y una cocina en la furgoneta.'::text),
(362300,40256,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'D''ici le week-end prochain, les deux hommes ... une douche et une cuisine dans le van.'::text,'auront installé'::text,'installeront'::text,'seront en train d''installer'::text,'D''ici le week-end prochain, les deux hommes auront installé une douche et une cuisine dans le van.'::text),
(362303,40256,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Önümüzdeki hafta sonuna kadar iki adam minibüse bir duş ve bir mutfak ...'::text,'kurmuş olacak'::text,'kuracak'::text,'kuruyor olacak'::text,'Önümüzdeki hafta sonuna kadar iki adam minibüse bir duş ve bir mutfak kurmuş olacak.'::text),
(362304,40256,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Jövő hétvégére a két férfi ... egy zuhanyt és egy konyhát a furgonba.'::text,'beszerel'::text,'be fog szerelni'::text,'szerelni fog'::text,'Jövő hétvégére a két férfi beszerel egy zuhanyt és egy konyhát a furgonba.'::text),
(362307,40257,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wären die Paneele nicht installiert worden, ... das Fahrzeug keine Energiequelle gehabt.'::text,'hätte'::text,'wird'::text,'hatte'::text,'Wären die Paneele nicht installiert worden, hätte das Fahrzeug keine Energiequelle gehabt.'::text),
(362311,40257,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якби панелі не встановили, транспортний засіб ... жодного джерела енергії.'::text,'не мав би'::text,'не матиме'::text,'не мав'::text,'Якби панелі не встановили, транспортний засіб не мав би жодного джерела енергії.'::text),
(362310,40257,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si los paneles no se hubieran instalado, el vehículo ... ninguna fuente de energía.'::text,'no habría tenido'::text,'no tendrá'::text,'no tenía'::text,'Si los paneles no se hubieran instalado, el vehículo no habría tenido ninguna fuente de energía.'::text),
(362309,40257,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si les panneaux n''avaient pas été installés, le véhicule ... aucune source d''énergie.'::text,'n''aurait eu'::text,'n''aura'::text,'n''avait'::text,'Si les panneaux n''avaient pas été installés, le véhicule n''aurait eu aucune source d''énergie.'::text),
(362312,40257,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Paneller takılmamış olsaydı, aracın hiçbir güç kaynağı ...'::text,'olmazdı'::text,'olmayacak'::text,'yoktu'::text,'Paneller takılmamış olsaydı, aracın hiçbir güç kaynağı olmazdı.'::text),
(362313,40257,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha a paneleket nem szerelték volna be, a járműnek ... áramforrása.'::text,'nem lett volna'::text,'nem lesz'::text,'nem volt'::text,'Ha a paneleket nem szerelték volna be, a járműnek nem lett volna áramforrása.'::text),
(362316,40258,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sein Kumpel beschuldigte ihn, die Solarpanels schief ... zu haben! Totaler Verrat!'::text,'montiert'::text,'montieren'::text,'montieren'::text,'Sein Kumpel beschuldigte ihn, die Solarpanels schief montiert zu haben! Totaler Verrat!'::text),
(362320,40258,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Друг звинуватив його в тому, що він ... сонячні панелі криво! Повна зрада!'::text,'встановив'::text,'встановити'::text,'встановити'::text,'Друг звинуватив його в тому, що він встановив сонячні панелі криво! Повна зрада!'::text),
(362319,40258,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Su amigo lo acusó de ... los paneles solares torcidos! ¡Traición total!'::text,'haber instalado'::text,'instalar'::text,'instalar'::text,'¡Su amigo lo acusó de haber instalado los paneles solares torcidos! ¡Traición total!'::text),
(362318,40258,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Son pote l''a accusé d''avoir ... les panneaux solaires de travers ! Trahison totale !'::text,'installé'::text,'installer'::text,'installer'::text,'Son pote l''a accusé d''avoir installé les panneaux solaires de travers ! Trahison totale !'::text),
(362321,40258,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Arkadaşı onu güneş panellerini yamuk ... suçladı! Tam bir ihanet!'::text,'taktığı için'::text,'takmakla'::text,'takmak'::text,'Arkadaşı onu güneş panellerini yamuk taktığı için suçladı! Tam bir ihanet!'::text),
(362322,40258,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A haverja azzal vádolta, hogy ferdén ... a napelemeket! Totális árulás!'::text,'szerelte fel'::text,'felszerelni'::text,'felszerelni'::text,'A haverja azzal vádolta, hogy ferdén szerelte fel a napelemeket! Totális árulás!'::text),
(362325,40259,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie ... den Dachrahmen vor dem Sturm einbauen sollen; der Regen hat fast alles zerstört!'::text,'hätten'::text,'müssen'::text,'hätten nicht'::text,'Sie hätten den Dachrahmen vor dem Sturm einbauen sollen; der Regen hat fast alles zerstört!'::text),
(362329,40259,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вони ... встановити каркас даху до бурі; дощ мало не зруйнував усе!'::text,'мали'::text,'мусили'::text,'не мусили'::text,'Вони мали встановити каркас даху до бурі; дощ мало не зруйнував усе!'::text),
(362328,40259,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ellos ... instalado el marco del techo antes de la tormenta; ¡la lluvia casi lo destruyó todo!'::text,'deberían haber'::text,'deben de haber'::text,'no tenían que haber'::text,'Ellos deberían haber instalado el marco del techo antes de la tormenta; ¡la lluvia casi lo destruyó todo!'::text),
(362327,40259,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ils ... installer la charpente du toit avant la tempête ; la pluie a presque tout détruit !'::text,'auraient dû'::text,'ont dû'::text,'n''avaient pas à'::text,'Ils auraient dû installer la charpente du toit avant la tempête ; la pluie a presque tout détruit !'::text),
(362330,40259,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Çatı iskeletini fırtınadan önce ...; yağmur neredeyse her şeyi mahvetti!'::text,'takmaları gerekirdi'::text,'takmış olmalılar'::text,'takmalarına gerek yoktu'::text,'Çatı iskeletini fırtınadan önce takmaları gerekirdi; yağmur neredeyse her şeyi mahvetti!'::text),
(362331,40259,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... volna beszerelni a tetőszerkezetet a vihar előtt; az eső majdnem mindent tönkretett!'::text,'Kellett'::text,'Biztos kellett'::text,'Nem kellett'::text,'Kellett volna beszerelni a tetőszerkezetet a vihar előtt; az eső majdnem mindent tönkretett!'::text),
(362343,40261,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Girl, er hat mir gesagt, er wünschte, er ... die Solarpanels vor dem Sommertrip montiert.'::text,'hätte'::text,'würde'::text,'hätte'::text,'Girl, er hat mir gesagt, er wünschte, er hätte die Solarpanels vor dem Sommertrip montiert.'::text),
(362347,40261,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Подруго, він сказав мені, що шкодує, що не ... сонячні панелі до літньої поїздки.'::text,'встановив'::text,'встановив би'::text,'встановив'::text,'Подруго, він сказав мені, що шкодує, що не встановив сонячні панелі до літньої поїздки.'::text),
(362346,40261,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Amiga, me dijo que ojalá ... los paneles solares antes del viaje de verano.'::text,'hubiera instalado'::text,'instalaría'::text,'instalara'::text,'Amiga, me dijo que ojalá hubiera instalado los paneles solares antes del viaje de verano.'::text),
(362345,40261,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Meuf, il m''a dit qu''il aimerait ... les panneaux solaires avant le voyage d''été.'::text,'avoir installé'::text,'installer'::text,'installer'::text,'Meuf, il m''a dit qu''il aimerait avoir installé les panneaux solaires avant le voyage d''été.'::text),
(362348,40261,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kızım, bana yaz tatilinden önce güneş panellerini keşke ... dedi.'::text,'takmış olsaydım'::text,'taksam'::text,'taktım'::text,'Kızım, bana yaz tatilinden önce güneş panellerini keşke takmış olsaydım dedi.'::text),
(362349,40261,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Csajszi, azt mondta, bárcsak ... a napelemeket a nyári út előtt.'::text,'felszerelte volna'::text,'felszerelné'::text,'felszerelte'::text,'Csajszi, azt mondta, bárcsak felszerelte volna a napelemeket a nyári út előtt.'::text),
(362352,40262,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bestie, anscheinend hat der Besitzer, ... Freunde die ganze Küche eingebaut haben, eine Stunde lang getanzt.'::text,'dessen'::text,'der'::text,'das'::text,'Bestie, anscheinend hat der Besitzer, dessen Freunde die ganze Küche eingebaut haben, eine Stunde lang getanzt.'::text),
(362356,40262,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Подружко, кажуть, власник, ... друзі встановили всю кухню, танцював цілу годину.'::text,'чиї'::text,'який'::text,'що'::text,'Подружко, кажуть, власник, чиї друзі встановили всю кухню, танцював цілу годину.'::text),
(362355,40262,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Amiga, al parecer el dueño, ... amigos instalaron toda la cocina, bailó una hora.'::text,'cuyos'::text,'que'::text,'el cual'::text,'Amiga, al parecer el dueño, cuyos amigos instalaron toda la cocina, bailó una hora.'::text),
(362354,40262,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bestie, apparemment le propriétaire, ... amis ont installé toute la cuisine, a dansé une heure.'::text,'dont les'::text,'qui'::text,'lequel'::text,'Bestie, apparemment le propriétaire, dont les amis ont installé toute la cuisine, a dansé une heure.'::text),
(362357,40262,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kızım, duyduğuma göre ... arkadaşları bütün mutfağı kuran ev sahibi bir saat dans etmiş.'::text,''::text,NULL::text,NULL::text,'Kızım, duyduğuma göre arkadaşları bütün mutfağı kuran ev sahibi bir saat dans etmiş.'::text),
(362358,40262,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Csajszi, állítólag a tulaj, ... barátai beszerelték az egész konyhát, egy órán át táncolt.'::text,'akinek a'::text,'aki'::text,'ami'::text,'Csajszi, állítólag a tulaj, akinek a barátai beszerelték az egész konyhát, egy órán át táncolt.'::text),
(362361,40263,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Männer haben zuerst die Solarpanels montiert, ... der Van Strom für die Werkzeuge hat.'::text,'damit'::text,'falls'::text,'obwohl'::text,'Die Männer haben zuerst die Solarpanels montiert, damit der Van Strom für die Werkzeuge hat.'::text),
(362365,40263,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Чоловіки спершу встановили сонячні панелі, ... фургон мав живлення для інструментів.'::text,'щоб'::text,'на випадок, якщо'::text,'хоча'::text,'Чоловіки спершу встановили сонячні панелі, щоб фургон мав живлення для інструментів.'::text),
(362364,40263,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Los hombres instalaron primero los paneles solares ... la furgoneta tuviera electricidad para las herramientas.'::text,'para que'::text,'por si'::text,'aunque'::text,'Los hombres instalaron primero los paneles solares para que la furgoneta tuviera electricidad para las herramientas.'::text),
(362363,40263,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Les hommes ont d''abord installé les panneaux solaires ... le van ait du courant pour les outils.'::text,'pour que'::text,'au cas où'::text,'même si'::text,'Les hommes ont d''abord installé les panneaux solaires pour que le van ait du courant pour les outils.'::text),
(362366,40263,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Adamlar güneş panellerini önce taktılar, ... minibüste aletler için elektrik olsun.'::text,'ki'::text,'ne olur ne olmaz'::text,'gerçi'::text,'Adamlar güneş panellerini önce taktılar, ki minibüste aletler için elektrik olsun.'::text),
(362367,40263,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A férfiak először a napelemeket szerelték fel, ... a furgonban legyen áram a szerszámokhoz.'::text,'hogy'::text,'arra az esetre, ha'::text,'bár'::text,'A férfiak először a napelemeket szerelték fel, hogy a furgonban legyen áram a szerszámokhoz.'::text),
(369957,41107,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ganz ehrlich, du ... dein Motorrad so lässig vom Truck, als ich anfing zu filmen.'::text,'zogst'::text,'zogst'::text,'hast gezogen'::text,'Ganz ehrlich, du zogst dein Motorrad so lässig vom Truck, als ich anfing zu filmen.'::text),
(369961,41107,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Чесно, ти ... свій мотоцикл з вантажівки так плавно, коли я почав знімати.'::text,'знімав'::text,'зняв'::text,'зняв'::text,'Чесно, ти знімав свій мотоцикл з вантажівки так плавно, коли я почав знімати.'::text),
(369960,41107,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'No voy a mentir, ... tu moto del camión con tanta soltura cuando empecé a grabar.'::text,'estabas sacando'::text,'sacaste'::text,'has sacado'::text,'No voy a mentir, estabas sacando tu moto del camión con tanta soltura cuando empecé a grabar.'::text),
(369959,41107,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Je vais pas mentir, tu ... ta moto du camion avec tellement d''aisance quand j''ai commencé à filmer.'::text,'sortais'::text,'as sorti'::text,'as sorti'::text,'Je vais pas mentir, tu sortais ta moto du camion avec tellement d''aisance quand j''ai commencé à filmer.'::text),
(369962,41107,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yalan yok, ben çekmeye başladığımda motosikletini kamyondan çok rahat ...'::text,'indiriyordun'::text,'indirdin'::text,'indirdin'::text,'Yalan yok, ben çekmeye başladığımda motosikletini kamyondan çok rahat indiriyordun.'::text),
(369963,41107,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nem hazudok, amikor elkezdtem forgatni, olyan lazán ... le a motorodat a teherautóról.'::text,'vetted'::text,'vetted'::text,'vetted'::text,'Nem hazudok, amikor elkezdtem forgatni, olyan lazán vetted le a motorodat a teherautóról.'::text),
(369966,41108,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Du ... das Motorrad jetzt schon seit zwei Jahren über deinen Truck. Respekt.'::text,'lädst'::text,'lädst'::text,'lädst'::text,'Du lädst das Motorrad jetzt schon seit zwei Jahren über deinen Truck. Respekt.'::text),
(369970,41108,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ти вже два роки ... цей мотоцикл від своєї вантажівки. Респект.'::text,'заряджаєш'::text,'заряджаєш'::text,'заряджаєш'::text,'Ти вже два роки заряджаєш цей мотоцикл від своєї вантажівки. Респект.'::text),
(369969,41108,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Llevas dos años ... esa moto desde tu camión. Respeto.'::text,'cargando'::text,'estás cargando'::text,'cargas'::text,'Llevas dos años cargando esa moto desde tu camión. Respeto.'::text),
(369968,41108,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tu ... cette moto sur ton camion depuis deux ans. Respect.'::text,'recharges'::text,'recharges'::text,'recharges'::text,'Tu recharges cette moto sur ton camion depuis deux ans. Respect.'::text),
(369971,41108,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'İki yıldır ... o motosikleti kamyonundan. Helal olsun.'::text,'şarj ediyorsun'::text,'şarj ediyorsun'::text,'şarj edersin'::text,'İki yıldır şarj ediyorsun o motosikleti kamyonundan. Helal olsun.'::text),
(369972,41108,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Már két éve ... azt a motort a teherautódról. Respekt.'::text,'töltöd'::text,'töltöd'::text,'töltöd'::text,'Már két éve töltöd azt a motort a teherautódról. Respekt.'::text),
(369975,41109,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er ... das Motorrad mit einer einzigen fließenden Bewegung aus der Halterung. Ein echter Profi.'::text,'zog'::text,'zog gerade'::text,'hat gezogen'::text,'Er zog das Motorrad mit einer einzigen fließenden Bewegung aus der Halterung. Ein echter Profi.'::text),
(369979,41109,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він ... мотоцикл із кріплення одним плавним рухом. Справжній профі.'::text,'витягнув'::text,'витягував'::text,'витягнув'::text,'Він витягнув мотоцикл із кріплення одним плавним рухом. Справжній профі.'::text),
(369978,41109,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Él ... la moto del soporte en un solo movimiento suave. Todo un profesional.'::text,'sacó'::text,'estaba sacando'::text,'ha sacado'::text,'Él sacó la moto del soporte en un solo movimiento suave. Todo un profesional.'::text),
(369977,41109,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il ... la moto de son support d''un seul geste fluide. Un vrai pro.'::text,'a sorti'::text,'sortait'::text,'a sorti'::text,'Il a sorti la moto de son support d''un seul geste fluide. Un vrai pro.'::text),
(369980,41109,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Motosikleti tek bir akıcı hareketle ... yuvasından. Tam bir profesyonel.'::text,'çıkardı'::text,'çıkarıyordu'::text,'çıkardı'::text,'Motosikleti tek bir akıcı hareketle çıkardı yuvasından. Tam bir profesyonel.'::text),
(369981,41109,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Egyetlen laza mozdulattal ... a motort a tartóból. Igazi profi.'::text,'húzta ki'::text,'húzta ki'::text,'húzta ki'::text,'Egyetlen laza mozdulattal húzta ki a motort a tartóból. Igazi profi.'::text),
(369984,41110,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er ... sein Motorrad heute zweimal über den Truck geladen. Anstrengende Arbeit, offensichtlich.'::text,'hat'::text,'hat'::text,'lädt'::text,'Er hat sein Motorrad heute zweimal über den Truck geladen. Anstrengende Arbeit, offensichtlich.'::text),
(369988,41110,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він сьогодні двічі ... свій мотоцикл від вантажівки. Виснажлива робота, очевидно.'::text,'зарядив'::text,'заряджав'::text,'заряджає'::text,'Він сьогодні двічі зарядив свій мотоцикл від вантажівки. Виснажлива робота, очевидно.'::text),
(369987,41110,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Él ... su moto desde el camión dos veces hoy. Un trabajo agotador, obviamente.'::text,'ha cargado'::text,'ha estado cargando'::text,'carga'::text,'Él ha cargado su moto desde el camión dos veces hoy. Un trabajo agotador, obviamente.'::text),
(369986,41110,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il ... sa moto sur le camion deux fois aujourd''hui. Un travail épuisant, évidemment.'::text,'a rechargé'::text,'recharge'::text,'recharge'::text,'Il a rechargé sa moto sur le camion deux fois aujourd''hui. Un travail épuisant, évidemment.'::text),
(369989,41110,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bugün iki kez ... motosikletini kamyondan. Yorucu bir iş, belli ki.'::text,'şarj etti'::text,'şarj ediyordu'::text,'şarj ediyor'::text,'Bugün iki kez şarj etti motosikletini kamyondan. Yorucu bir iş, belli ki.'::text),
(369990,41110,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ma kétszer ... a motorját a teherautóról. Kimerítő munka, nyilván.'::text,'töltötte fel'::text,'töltötte'::text,'tölti'::text,'Ma kétszer töltötte fel a motorját a teherautóról. Kimerítő munka, nyilván.'::text),
(369993,41111,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er ... das Motorrad rausgeholt, bevor er das Bett überhaupt erwähnte. Offensichtlich das Wichtigste.'::text,'hatte'::text,'hat'::text,'holt'::text,'Er hatte das Motorrad rausgeholt, bevor er das Bett überhaupt erwähnte. Offensichtlich das Wichtigste.'::text),
(369997,41111,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він ... мотоцикл ще до того, як узагалі згадав про ліжко. Очевидно, головне.'::text,'витягнув'::text,'витягнув'::text,'витягує'::text,'Він витягнув мотоцикл ще до того, як узагалі згадав про ліжко. Очевидно, головне.'::text),
(369996,41111,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Él ... la moto antes de mencionar siquiera la cama. Obviamente, lo principal.'::text,'había sacado'::text,'ha sacado'::text,'saca'::text,'Él había sacado la moto antes de mencionar siquiera la cama. Obviamente, lo principal.'::text),
(369995,41111,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il ... la moto avant même de parler du lit. Évidemment l''essentiel.'::text,'avait sorti'::text,'a sorti'::text,'sort'::text,'Il avait sorti la moto avant même de parler du lit. Évidemment l''essentiel.'::text),
(369998,41111,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Motosikleti ... daha yataktan bahsetmeden. Belli ki asıl önemli olan o.'::text,'çıkarmıştı'::text,'çıkardı'::text,'çıkarıyor'::text,'Motosikleti çıkarmıştı daha yataktan bahsetmeden. Belli ki asıl önemli olan o.'::text),
(369999,41111,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Már azelőtt ... a motort, hogy egyáltalán megemlítette volna az ágyat. Nyilván ez a lényeg.'::text,'kivette'::text,'kivette'::text,'kiveszi'::text,'Már azelőtt kivette a motort, hogy egyáltalán megemlítette volna az ágyat. Nyilván ez a lényeg.'::text),
(370002,41112,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn die Batterie des Trucks leer ist, ... sich das Motorrad nie wieder laden lassen! Katastrophe!'::text,'wird'::text,'würde'::text,NULL::text,'Wenn die Batterie des Trucks leer ist, wird sich das Motorrad nie wieder laden lassen! Katastrophe!'::text),
(370006,41112,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якщо акумулятор вантажівки сяде, мотоцикл більше ніколи не ... заряджатися! Катастрофа!'::text,'буде'::text,NULL::text,NULL::text,'Якщо акумулятор вантажівки сяде, мотоцикл більше ніколи не буде заряджатися! Катастрофа!'::text),
(370005,41112,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Si la batería del camión se agota, la moto ... nunca más se cargará! ¡Desastre!'::text,''::text,NULL::text,NULL::text,'¡Si la batería del camión se agota, la moto nunca más se cargará! ¡Desastre!'::text),
(370004,41112,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si la batterie du camion lâche, la moto ... ne se rechargera plus jamais ! Catastrophe !'::text,''::text,NULL::text,NULL::text,'Si la batterie du camion lâche, la moto ne se rechargera plus jamais ! Catastrophe !'::text),
(370007,41112,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kamyonun aküsü biterse, motosiklet bir daha asla şarj ...! Felaket!'::text,'olmayacak'::text,'olmazdı'::text,NULL::text,'Kamyonun aküsü biterse, motosiklet bir daha asla şarj olmayacak! Felaket!'::text),
(370008,41112,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha lemerül a teherautó akkuja, a motor soha többé nem ... feltöltődni! Katasztrófa!'::text,'fog'::text,NULL::text,NULL::text,'Ha lemerül a teherautó akkuja, a motor soha többé nem fog feltöltődni! Katasztrófa!'::text),
(370011,41113,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn jemand mein Motorrad von diesem Truck ..., wäre das das Ende von allem!'::text,'klauen würde'::text,'klaut'::text,'klauen würde'::text,'Wenn jemand mein Motorrad von diesem Truck klauen würde, wäre das das Ende von allem!'::text),
(370015,41113,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якби хтось ... мій мотоцикл із цієї вантажівки, це був би кінець усього!'::text,'вкрав'::text,'вкраде'::text,'вкрав би'::text,'Якби хтось вкрав мій мотоцикл із цієї вантажівки, це був би кінець усього!'::text),
(370014,41113,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Si alguien ... mi moto de este camión, sería el fin de todo!'::text,'robara'::text,'roba'::text,'robaría'::text,'¡Si alguien robara mi moto de este camión, sería el fin de todo!'::text),
(370013,41113,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si quelqu''un ... ma moto de ce camion, ce serait la fin de tout !'::text,'volait'::text,'vole'::text,'volerait'::text,'Si quelqu''un volait ma moto de ce camion, ce serait la fin de tout !'::text),
(370016,41113,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Biri motosikletimi bu kamyondan ..., her şeyin sonu olurdu!'::text,'çalsa'::text,'çalıyor'::text,'çalardı'::text,'Biri motosikletimi bu kamyondan çalsa, her şeyin sonu olurdu!'::text),
(370017,41113,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha valaki ... a motoromat erről a teherautóról, az mindennek a vége lenne!'::text,'ellopná'::text,'ellopja'::text,'ellopná'::text,'Ha valaki ellopná a motoromat erről a teherautóról, az mindennek a vége lenne!'::text),
(370029,41115,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Mann ... das Motorrad aus der Halterung an der Seite des Trucks.'::text,'zieht'::text,'wird gezogen'::text,'ziehend'::text,'Der Mann zieht das Motorrad aus der Halterung an der Seite des Trucks.'::text),
(370033,41115,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Чоловік ... мотоцикл із кріплення збоку вантажівки.'::text,'витягує'::text,'витягується'::text,'витягування'::text,'Чоловік витягує мотоцикл із кріплення збоку вантажівки.'::text),
(370032,41115,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El hombre ... la moto del soporte en el lateral del camión.'::text,'saca'::text,'es sacado'::text,'sacando'::text,'El hombre saca la moto del soporte en el lateral del camión.'::text),
(370031,41115,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'L''homme ... la moto du support sur le côté du camion.'::text,'sort'::text,'est sorti'::text,'sortant'::text,'L''homme sort la moto du support sur le côté du camion.'::text),
(370034,41115,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Adam motosikleti kamyonun yanındaki yuvadan ...'::text,'çıkarıyor'::text,'çıkarılıyor'::text,'çıkarma'::text,'Adam motosikleti kamyonun yanındaki yuvadan çıkarıyor.'::text),
(370035,41115,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A férfi ... a motort a teherautó oldalán lévő tartóból.'::text,'húzza ki'::text,'ki van húzva'::text,'kihúzva'::text,'A férfi húzza ki a motort a teherautó oldalán lévő tartóból.'::text),
(370038,41116,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Mann lädt sein Motorrad mit ... aus seinem Truck.'::text,'Strom'::text,'einem Strom'::text,'den Strömen'::text,'Der Mann lädt sein Motorrad mit Strom aus seinem Truck.'::text),
(370042,41116,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Чоловік заряджає свій мотоцикл ... від своєї вантажівки.'::text,'електрикою'::text,'електрикою'::text,'електриками'::text,'Чоловік заряджає свій мотоцикл електрикою від своєї вантажівки.'::text),
(370041,41116,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El hombre carga su moto con ... de su camión.'::text,'electricidad'::text,'una electricidad'::text,'las electricidades'::text,'El hombre carga su moto con electricidad de su camión.'::text),
(370040,41116,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'L''homme recharge sa moto avec ... de son camion.'::text,'l''électricité'::text,'une électricité'::text,'les électricités'::text,'L''homme recharge sa moto avec l''électricité de son camion.'::text),
(370043,41116,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Adam motosikletini kamyonundan gelen ... şarj ediyor.'::text,'elektrikle'::text,'bir elektrikle'::text,'elektriklerle'::text,'Adam motosikletini kamyonundan gelen elektrikle şarj ediyor.'::text),
(370044,41116,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A férfi a teherautójából származó ... tölti a motorját.'::text,'árammal'::text,'egy árammal'::text,'az áramokkal'::text,'A férfi a teherautójából származó árammal tölti a motorját.'::text),
(363234,40360,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Hund ... um Mitternacht auf der Tastatur, also schlief er nicht.'::text,'tippte'::text,'tippte'::text,'hat getippt'::text,'Der Hund tippte um Mitternacht auf der Tastatur, also schlief er nicht.'::text),
(363238,40360,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Пес опівночі ... на клавіатурі, тож він не спав.'::text,'друкував'::text,'надрукував'::text,'надрукував'::text,'Пес опівночі друкував на клавіатурі, тож він не спав.'::text),
(363237,40360,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El perro ... en el teclado a medianoche, así que no estaba dormido.'::text,'estaba escribiendo'::text,'escribió'::text,'ha escrito'::text,'El perro estaba escribiendo en el teclado a medianoche, así que no estaba dormido.'::text),
(363236,40360,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le chien ... sur le clavier à minuit, donc il ne dormait pas.'::text,'tapait'::text,'a tapé'::text,'a tapé'::text,'Le chien tapait sur le clavier à minuit, donc il ne dormait pas.'::text),
(363239,40360,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Köpek gece yarısı klavyede ..., yani uyumuyordu.'::text,'yazıyordu'::text,'yazdı'::text,'yazdı'::text,'Köpek gece yarısı klavyede yazıyordu, yani uyumuyordu.'::text),
(363240,40360,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A kutya éjfélkor ... a billentyűzeten, tehát nem aludt.'::text,'gépelt'::text,'gépelt'::text,'gépelt'::text,'A kutya éjfélkor gépelt a billentyűzeten, tehát nem aludt.'::text),
(363243,40361,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bestie, anscheinend ... dieser Hund seit 21 Uhr auf seiner Tastatur.'::text,'tippt'::text,'tippt'::text,'tippt'::text,'Bestie, anscheinend tippt dieser Hund seit 21 Uhr auf seiner Tastatur.'::text),
(363247,40361,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Подружко, кажуть, цей пес ... на своїй клавіатурі з 21:00.'::text,'друкує'::text,'друкує'::text,'друкує'::text,'Подружко, кажуть, цей пес друкує на своїй клавіатурі з 21:00.'::text),
(363246,40361,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Amiga, al parecer ese perro lleva ... en su teclado desde las 21:00.'::text,'escribiendo'::text,'está escribiendo'::text,'escribe'::text,'Amiga, al parecer ese perro lleva escribiendo en su teclado desde las 21:00.'::text),
(363245,40361,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bestie, apparemment ce chien ... sur son clavier depuis 21 h.'::text,'tape'::text,'tape'::text,'tape'::text,'Bestie, apparemment ce chien tape sur son clavier depuis 21 h.'::text),
(363248,40361,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kızım, duyduğuma göre o köpek saat 21.00''den beri klavyesinde ...'::text,'yazıyor'::text,'yazıyor'::text,'yazar'::text,'Kızım, duyduğuma göre o köpek saat 21.00''den beri klavyesinde yazıyor.'::text),
(363249,40361,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Csajszi, állítólag az a kutya este 9 óta ... a billentyűzetén.'::text,'gépel'::text,'gépel'::text,'gépel'::text,'Csajszi, állítólag az a kutya este 9 óta gépel a billentyűzetén.'::text),
(363252,40362,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hör zu, sie hat mir erzählt, der Hund ... seine Brille auf, setzte sich und haute in die Tastatur.'::text,'setzte'::text,'setzte gerade'::text,'hat gesetzt'::text,'Hör zu, sie hat mir erzählt, der Hund setzte seine Brille auf, setzte sich und haute in die Tastatur.'::text),
(363256,40362,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Слухай, вона мені сказала, що пес ... окуляри, сів і вдарив по клавіатурі.'::text,'начепив'::text,'чіпляв'::text,'начепив'::text,'Слухай, вона мені сказала, що пес начепив окуляри, сів і вдарив по клавіатурі.'::text),
(363255,40362,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Escucha, me dijo que el perro ... sus gafas, se sentó y le dio al teclado.'::text,'se puso'::text,'se estaba poniendo'::text,'se ha puesto'::text,'Escucha, me dijo que el perro se puso sus gafas, se sentó y le dio al teclado.'::text),
(363254,40362,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Écoute, elle m''a dit que le chien ... ses lunettes, s''est assis et a tapé sur le clavier.'::text,'a mis'::text,'mettait'::text,'a mis'::text,'Écoute, elle m''a dit que le chien a mis ses lunettes, s''est assis et a tapé sur le clavier.'::text),
(363257,40362,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dinle, bana dediğine göre köpek gözlüğünü ..., oturdu ve klavyeye vurdu.'::text,'taktı'::text,'takıyordu'::text,'taktı'::text,'Dinle, bana dediğine göre köpek gözlüğünü taktı, oturdu ve klavyeye vurdu.'::text),
(363258,40362,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Figyelj, azt mondta, hogy a kutya ... a szemüvegét, leült és rácsapott a billentyűzetre.'::text,'feltette'::text,'feltette'::text,'feltette'::text,'Figyelj, azt mondta, hogy a kutya feltette a szemüvegét, leült és rácsapott a billentyűzetre.'::text),
(363261,40363,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Hund ... heute Abend 3.000 Wörter auf dieser Tastatur getippt. Eindeutig ein normales Haustier.'::text,'hat'::text,'hat'::text,'tippt'::text,'Der Hund hat heute Abend 3.000 Wörter auf dieser Tastatur getippt. Eindeutig ein normales Haustier.'::text),
(363265,40363,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Пес сьогодні ввечері ... на тій клавіатурі 3 000 слів. Явно звичайний домашній улюбленець.'::text,'надрукував'::text,'друкував'::text,'друкує'::text,'Пес сьогодні ввечері надрукував на тій клавіатурі 3 000 слів. Явно звичайний домашній улюбленець.'::text),
(363264,40363,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El perro ... 3.000 palabras en ese teclado esta noche. Claramente una mascota normal.'::text,'ha escrito'::text,'ha estado escribiendo'::text,'escribe'::text,'El perro ha escrito 3.000 palabras en ese teclado esta noche. Claramente una mascota normal.'::text),
(363263,40363,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le chien ... 3 000 mots sur ce clavier ce soir. Clairement un animal normal.'::text,'a tapé'::text,'tape'::text,'tape'::text,'Le chien a tapé 3 000 mots sur ce clavier ce soir. Clairement un animal normal.'::text),
(363266,40363,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Köpek bu akşam ... 3.000 kelime o klavyede. Belli ki normal bir evcil hayvan.'::text,'yazdı'::text,'yazıyor'::text,'yazar'::text,'Köpek bu akşam yazdı 3.000 kelime o klavyede. Belli ki normal bir evcil hayvan.'::text),
(363267,40363,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A kutya ma este 3000 szót ... azon a billentyűzeten. Egyértelműen egy átlagos háziállat.'::text,'gépelt be'::text,'gépelt'::text,'gépel'::text,'A kutya ma este 3000 szót gépelt be azon a billentyűzeten. Egyértelműen egy átlagos háziállat.'::text),
(363270,40364,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mitternacht? Dieser Hund ... lange an seiner Tastatur arbeiten. Makellose Lebensentscheidungen.'::text,'muss'::text,'kann nicht'::text,'darf nicht'::text,'Mitternacht? Dieser Hund muss lange an seiner Tastatur arbeiten. Makellose Lebensentscheidungen.'::text),
(363274,40364,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Північ? Цей пес ... працювати допізна за своєю клавіатурою. Бездоганні життєві рішення.'::text,'мусить'::text,'не може'::text,'не повинен'::text,'Північ? Цей пес мусить працювати допізна за своєю клавіатурою. Бездоганні життєві рішення.'::text),
(363273,40364,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¿Medianoche? Ese perro ... estar trabajando hasta tarde en su teclado. Decisiones de vida impecables.'::text,'debe de'::text,'no puede'::text,'no debe'::text,'¿Medianoche? Ese perro debe de estar trabajando hasta tarde en su teclado. Decisiones de vida impecables.'::text),
(363272,40364,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Minuit ? Ce chien ... travailler tard sur son clavier. Des choix de vie impeccables.'::text,'doit'::text,'ne peut pas'::text,'ne doit pas'::text,'Minuit ? Ce chien doit travailler tard sur son clavier. Des choix de vie impeccables.'::text),
(363275,40364,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Gece yarısı mı? O köpek geç saate kadar çalışıyor ... klavyesinin başında. Kusursuz hayat tercihleri.'::text,'olmalı'::text,'olamaz'::text,'olmamalı'::text,'Gece yarısı mı? O köpek geç saate kadar çalışıyor olmalı klavyesinin başında. Kusursuz hayat tercihleri.'::text),
(363276,40364,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Éjfél? Az a kutya ... későig dolgozik a billentyűzetén. Hibátlan életdöntések.'::text,'biztosan'::text,'biztos nem'::text,'nem szabad, hogy'::text,'Éjfél? Az a kutya biztosan későig dolgozik a billentyűzetén. Hibátlan életdöntések.'::text),
(363279,40365,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Das Fenster, ... der Hund an der Tastatur sitzt, ist das einzige beleuchtete.'::text,'wo'::text,'das'::text,'der'::text,'Das Fenster, wo der Hund an der Tastatur sitzt, ist das einzige beleuchtete.'::text),
(363283,40365,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вікно, ... пес сидить за клавіатурою, — єдине освітлене.'::text,'де'::text,'яке'::text,'хто'::text,'Вікно, де пес сидить за клавіатурою, — єдине освітлене.'::text),
(363282,40365,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La ventana ... el perro está sentado frente al teclado es la única iluminada.'::text,'donde'::text,'que'::text,'quien'::text,'La ventana donde el perro está sentado frente al teclado es la única iluminada.'::text),
(363281,40365,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La fenêtre ... le chien est assis au clavier est la seule éclairée.'::text,'où'::text,'que'::text,'qui'::text,'La fenêtre où le chien est assis au clavier est la seule éclairée.'::text),
(363284,40365,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Köpeğin ... klavyenin başında oturduğu pencere, ışığı yanan tek pencere.'::text,''::text,NULL::text,NULL::text,'Köpeğin klavyenin başında oturduğu pencere, ışığı yanan tek pencere.'::text),
(363285,40365,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Az ablak, ... a kutya a billentyűzetnél ül, az egyetlen kivilágított.'::text,'ahol'::text,'amely'::text,'aki'::text,'Az ablak, ahol a kutya a billentyűzetnél ül, az egyetlen kivilágított.'::text),
(363288,40366,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Nachbar sagte, der Hund ... in der Nacht davor bis Mitternacht auf seiner Tastatur getippt.'::text,'hatte'::text,'hat'::text,'tippt'::text,'Der Nachbar sagte, der Hund hatte in der Nacht davor bis Mitternacht auf seiner Tastatur getippt.'::text),
(363292,40366,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Сусід сказав, що пес попередньої ночі ... на своїй клавіатурі до півночі.'::text,'друкував'::text,'друкував'::text,'друкує'::text,'Сусід сказав, що пес попередньої ночі друкував на своїй клавіатурі до півночі.'::text),
(363291,40366,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El vecino dijo que el perro ... en su teclado hasta medianoche la noche anterior.'::text,'había escrito'::text,'ha escrito'::text,'escribe'::text,'El vecino dijo que el perro había escrito en su teclado hasta medianoche la noche anterior.'::text),
(363290,40366,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le voisin a dit que le chien ... sur son clavier jusqu''à minuit la veille.'::text,'avait tapé'::text,'a tapé'::text,'tape'::text,'Le voisin a dit que le chien avait tapé sur son clavier jusqu''à minuit la veille.'::text),
(363293,40366,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Komşu, köpeğin önceki gece gece yarısına kadar klavyesinde ... söyledi.'::text,'yazmış olduğunu'::text,'yazdığını'::text,'yazdığını'::text,'Komşu, köpeğin önceki gece gece yarısına kadar klavyesinde yazmış olduğunu söyledi.'::text),
(363294,40366,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A szomszéd azt mondta, hogy a kutya előző éjjel éjfélig ... a billentyűzetén.'::text,'gépelt'::text,'gépelt'::text,'gépel'::text,'A szomszéd azt mondta, hogy a kutya előző éjjel éjfélig gépelt a billentyűzetén.'::text),
(363297,40367,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Hund ... Angst vor der Tastatur, aber jetzt tippt er jede Nacht.'::text,'hatte früher'::text,'hatte immer'::text,'ist gewohnt'::text,'Der Hund hatte früher Angst vor der Tastatur, aber jetzt tippt er jede Nacht.'::text),
(363301,40367,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Пес ... боявся клавіатури, але тепер друкує щоночі.'::text,'колись'::text,'бувало'::text,'звик'::text,'Пес колись боявся клавіатури, але тепер друкує щоночі.'::text),
(363300,40367,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El perro ... tenerle miedo al teclado, pero ahora escribe todas las noches.'::text,'solía'::text,'solía'::text,'está acostumbrado a'::text,'El perro solía tenerle miedo al teclado, pero ahora escribe todas las noches.'::text),
(363299,40367,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le chien ... peur du clavier, mais maintenant il tape toutes les nuits.'::text,'avait autrefois'::text,'avait'::text,'a l''habitude d''avoir'::text,'Le chien avait autrefois peur du clavier, mais maintenant il tape toutes les nuits.'::text),
(363302,40367,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Köpek klavyeden ..., ama artık her gece yazıyor.'::text,'eskiden korkardı'::text,'korkardı'::text,'korkmaya alışkın'::text,'Köpek klavyeden eskiden korkardı, ama artık her gece yazıyor.'::text),
(363303,40367,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A kutya ... félt a billentyűzettől, de most minden éjjel gépel.'::text,'régen'::text,'régen'::text,'hozzászokott'::text,'A kutya régen félt a billentyűzettől, de most minden éjjel gépel.'::text),
(363315,40369,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bemerkenswerterweise ... das Exemplar nun schon seit über einer Stunde an der Tastatur.'::text,'sitzt'::text,'sitzt'::text,'sitzt'::text,'Bemerkenswerterweise sitzt das Exemplar nun schon seit über einer Stunde an der Tastatur.'::text),
(363319,40369,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Примітно, що екземпляр ... за клавіатурою вже понад годину.'::text,'сидить'::text,'сидить'::text,'сидить'::text,'Примітно, що екземпляр сидить за клавіатурою вже понад годину.'::text),
(363318,40369,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Curiosamente, el ejemplar lleva ... frente al teclado más de una hora.'::text,'sentado'::text,'está sentado'::text,'se sienta'::text,'Curiosamente, el ejemplar lleva sentado frente al teclado más de una hora.'::text),
(363317,40369,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Fait remarquable, le spécimen ... au clavier depuis plus d''une heure.'::text,'est assis'::text,'est assis'::text,'s''assoit'::text,'Fait remarquable, le spécimen est assis au clavier depuis plus d''une heure.'::text),
(363320,40369,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dikkat çekici biçimde, örnek bir saati aşkın süredir klavyenin başında ...'::text,'oturuyor'::text,'oturuyor'::text,'oturur'::text,'Dikkat çekici biçimde, örnek bir saati aşkın süredir klavyenin başında oturuyor.'::text),
(363321,40369,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Figyelemre méltó módon a példány már több mint egy órája ... a billentyűzetnél.'::text,'ül'::text,'ül'::text,'ül'::text,'Figyelemre méltó módon a példány már több mint egy órája ül a billentyűzetnél.'::text),
(352407,39157,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn Leute Paviane aus Autos füttern, ... die Paviane zu den Autos zurück.'::text,'kommen'::text,'kamen'::text,'werden'::text,'Wenn Leute Paviane aus Autos füttern, kommen die Paviane zu den Autos zurück.'::text),
(352411,39157,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якщо люди годують павіанів з машин, павіани ... до машин.'::text,'повертаються'::text,'повернулися'::text,'повернуться'::text,'Якщо люди годують павіанів з машин, павіани повертаються до машин.'::text),
(352410,39157,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si la gente alimenta a los babuinos desde los coches, los babuinos ... a los coches.'::text,'vuelven'::text,'volvieron'::text,'volverán'::text,'Si la gente alimenta a los babuinos desde los coches, los babuinos vuelven a los coches.'::text),
(352409,39157,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si les gens nourrissent les babouins depuis les voitures, les babouins ... vers les voitures.'::text,'reviennent'::text,'sont revenus'::text,'reviendront'::text,'Si les gens nourrissent les babouins depuis les voitures, les babouins reviennent vers les voitures.'::text),
(352412,39157,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'İnsanlar babunları arabalardan beslerse, babunlar arabalara geri ...'::text,'gelir'::text,'geldi'::text,'gelecek'::text,'İnsanlar babunları arabalardan beslerse, babunlar arabalara geri gelir.'::text),
(352413,39157,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha az emberek az autókból etetik a páviánokat, a páviánok ... az autókhoz.'::text,'visszajönnek'::text,'visszajöttek'::text,'vissza fognak jönni'::text,'Ha az emberek az autókból etetik a páviánokat, a páviánok visszajönnek az autókhoz.'::text),
(352425,39159,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Fahrer wollte die Paviane füttern, und sein Kumpel auf dem Rücksitz ...'::text,'auch'::text,'war auch'::text,'auch nicht'::text,'Der Fahrer wollte die Paviane füttern, und sein Kumpel auf dem Rücksitz auch.'::text),
(352429,39159,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Водій хотів погодувати павіанів, і його друг на задньому сидінні ...'::text,'теж'::text,'теж був'::text,'теж ні'::text,'Водій хотів погодувати павіанів, і його друг на задньому сидінні теж.'::text),
(352428,39159,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El conductor quería dar de comer a los babuinos, y su amigo del asiento trasero ...'::text,'también'::text,'también estaba'::text,'tampoco'::text,'El conductor quería dar de comer a los babuinos, y su amigo del asiento trasero también.'::text),
(352427,39159,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le conducteur voulait nourrir les babouins, et son pote sur la banquette arrière ...'::text,'aussi'::text,'était aussi'::text,'non plus'::text,'Le conducteur voulait nourrir les babouins, et son pote sur la banquette arrière aussi.'::text),
(352430,39159,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Şoför babunları beslemek istedi, arka koltuktaki arkadaşı da ...'::text,'istedi'::text,'öyleydi'::text,'istemedi'::text,'Şoför babunları beslemek istedi, arka koltuktaki arkadaşı da istedi.'::text),
(352431,39159,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A sofőr meg akarta etetni a páviánokat, és a haverja a hátsó ülésen ...'::text,'is'::text,'is volt'::text,'sem'::text,'A sofőr meg akarta etetni a páviánokat, és a haverja a hátsó ülésen is.'::text),
(352434,39160,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Krass, anscheinend ... sie bis zum Ende der Tour jeden Pavian auf der Strecke gefüttert haben.'::text,'werden'::text,'werden'::text,'werden'::text,'Krass, anscheinend werden sie bis zum Ende der Tour jeden Pavian auf der Strecke gefüttert haben.'::text),
(352438,39160,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Та ну, кажуть, до кінця туру вони ... кожного павіана на дорозі.'::text,'нагодують'::text,'нагодують'::text,'годуватимуть'::text,'Та ну, кажуть, до кінця туру вони нагодують кожного павіана на дорозі.'::text),
(352437,39160,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'No puede ser, al parecer para el final del tour ... a todos los babuinos del camino.'::text,'habrán alimentado'::text,'alimentarán'::text,'estarán alimentando'::text,'No puede ser, al parecer para el final del tour habrán alimentado a todos los babuinos del camino.'::text),
(352436,39160,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sérieux, apparemment d''ici la fin du tour, ils ... tous les babouins de la piste.'::text,'auront nourri'::text,'nourriront'::text,'seront en train de nourrir'::text,'Sérieux, apparemment d''ici la fin du tour, ils auront nourri tous les babouins de la piste.'::text),
(352439,39160,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yok artık, duyduğuma göre turun sonuna kadar yoldaki her babunu ...'::text,'beslemiş olacaklar'::text,'besleyecekler'::text,'besliyor olacaklar'::text,'Yok artık, duyduğuma göre turun sonuna kadar yoldaki her babunu beslemiş olacaklar.'::text),
(352440,39160,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ne már, állítólag a túra végére ... az összes páviánt az úton.'::text,'megetetik'::text,'meg fogják etetni'::text,'etetni fogják'::text,'Ne már, állítólag a túra végére megetetik az összes páviánt az úton.'::text),
(352443,39161,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hätte ihnen niemand eine Banane gegeben, ... nicht drei Paviane auf der Motorhaube gesessen. Super gemacht, alle.'::text,'hätten'::text,'würden'::text,'saßen'::text,'Hätte ihnen niemand eine Banane gegeben, hätten nicht drei Paviane auf der Motorhaube gesessen. Super gemacht, alle.'::text),
(352447,39161,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якби ніхто не нагодував їх бананом, три павіани ... на капоті. Чудова робота, усі.'::text,'не сиділи б'::text,'не сиділи б'::text,'не сиділи'::text,'Якби ніхто не нагодував їх бананом, три павіани не сиділи б на капоті. Чудова робота, усі.'::text),
(352446,39161,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si nadie les hubiera dado un plátano, tres babuinos ... en el capó. Buen trabajo, todos.'::text,'no se habrían sentado'::text,'no se sentarían'::text,'no se sentaron'::text,'Si nadie les hubiera dado un plátano, tres babuinos no se habrían sentado en el capó. Buen trabajo, todos.'::text),
(352445,39161,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si personne ne leur avait donné de banane, trois babouins ... sur le capot. Bravo à tous.'::text,'ne se seraient pas assis'::text,'ne s''assiéraient pas'::text,'ne se sont pas assis'::text,'Si personne ne leur avait donné de banane, trois babouins ne se seraient pas assis sur le capot. Bravo à tous.'::text),
(352448,39161,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kimse onlara muz vermeseydi, üç babun ... kaputa. Harika iş çıkardınız, millet.'::text,'oturmazdı'::text,'oturmaz'::text,'oturmadı'::text,'Kimse onlara muz vermeseydi, üç babun oturmazdı kaputa. Harika iş çıkardınız, millet.'::text),
(352449,39161,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha senki nem etette volna meg őket banánnal, nem ... három pávián a motorháztetőn. Szép munka, mindenki.'::text,'ült volna'::text,'ülne'::text,'ült'::text,'Ha senki nem etette volna meg őket banánnal, nem ült volna három pávián a motorháztetőn. Szép munka, mindenki.'::text),
(352452,39162,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Guide hat uns gewarnt, die Paviane ... zu füttern. Also kam natürlich eine Banane auf die Motorhaube.'::text,'nicht'::text,'nicht'::text,'füttert nicht'::text,'Der Guide hat uns gewarnt, die Paviane nicht zu füttern. Also kam natürlich eine Banane auf die Motorhaube.'::text),
(352456,39162,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Гід попередив нас ... павіанів. Тож, звісно, банан опинився на капоті.'::text,'не годувати'::text,'не годуючи'::text,'не годуйте'::text,'Гід попередив нас не годувати павіанів. Тож, звісно, банан опинився на капоті.'::text),
(352455,39162,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El guía nos advirtió ... a los babuinos. Así que, obviamente, un plátano acabó en el capó.'::text,'que no alimentáramos'::text,'no alimentando'::text,'no alimentéis'::text,'El guía nos advirtió que no alimentáramos a los babuinos. Así que, obviamente, un plátano acabó en el capó.'::text),
(352454,39162,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le guide nous a avertis de ... les babouins. Du coup, évidemment, une banane a fini sur le capot.'::text,'ne pas nourrir'::text,'ne pas nourrissant'::text,'ne nourrissez pas'::text,'Le guide nous a avertis de ne pas nourrir les babouins. Du coup, évidemment, une banane a fini sur le capot.'::text),
(352457,39162,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Rehber bizi babunları ... konusunda uyardı. Yani tabii ki kaputa bir muz kondu.'::text,'beslememe'::text,'beslememek'::text,'beslemeyin'::text,'Rehber bizi babunları beslememe konusunda uyardı. Yani tabii ki kaputa bir muz kondu.'::text),
(352458,39162,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Az idegenvezető figyelmeztetett minket, hogy ... a páviánokat. Szóval nyilván egy banán került a motorháztetőre.'::text,'ne etessük'::text,'ne etetve'::text,'ne etessétek'::text,'Az idegenvezető figyelmeztetett minket, hogy ne etessük a páviánokat. Szóval nyilván egy banán került a motorháztetőre.'::text),
(352461,39163,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bro, jemand ... die Paviane gefüttert haben, weil drei von denen auf der Motorhaube sitzen.'::text,'muss'::text,'hätte'::text,'kann nicht'::text,'Bro, jemand muss die Paviane gefüttert haben, weil drei von denen auf der Motorhaube sitzen.'::text),
(352465,39163,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Бро, хтось ... павіанів, бо троє з них сидять на капоті.'::text,'точно нагодував'::text,'мав нагодувати'::text,'не міг нагодувати'::text,'Бро, хтось точно нагодував павіанів, бо троє з них сидять на капоті.'::text),
(352464,39163,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bro, alguien ... a los babuinos, porque tres están sentados en el capó.'::text,'debe de haber alimentado'::text,'debería haber alimentado'::text,'no puede haber alimentado'::text,'Bro, alguien debe de haber alimentado a los babuinos, porque tres están sentados en el capó.'::text),
(352463,39163,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Frère, quelqu''un ... les babouins, parce que y en a trois assis sur le capot.'::text,'a dû nourrir'::text,'aurait dû nourrir'::text,'n''a pas pu nourrir'::text,'Frère, quelqu''un a dû nourrir les babouins, parce que y en a trois assis sur le capot.'::text),
(352466,39163,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, biri babunları ..., çünkü üçü kaputta oturuyor.'::text,'beslemiş olmalı'::text,'beslemeliydi'::text,'beslemiş olamaz'::text,'Kanka, biri babunları beslemiş olmalı, çünkü üçü kaputta oturuyor.'::text),
(352467,39163,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tesó, valaki ... a páviánokat, mert hárman ülnek a motorháztetőn.'::text,'biztos megetette'::text,'meg kellett volna etetnie'::text,'nem etethette meg'::text,'Tesó, valaki biztos megetette a páviánokat, mert hárman ülnek a motorháztetőn.'::text),
(352479,39165,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ich wünschte, wir ... die Paviane nicht gefüttert; jetzt verzögern sie unser Meeting um 10 Uhr.'::text,'hätten'::text,'würden'::text,'fütterten'::text,'Ich wünschte, wir hätten die Paviane nicht gefüttert; jetzt verzögern sie unser Meeting um 10 Uhr.'::text),
(352483,39165,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Шкода, що ми ... павіанів; тепер вони затримують нашу нараду о 10:00.'::text,'нагодували'::text,'годуємо'::text,'годували б'::text,'Шкода, що ми нагодували павіанів; тепер вони затримують нашу нараду о 10:00.'::text),
(352482,39165,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ojalá no ... a los babuinos; ahora están retrasando nuestra reunión de las 10:00.'::text,'hubiéramos alimentado'::text,'alimentáramos'::text,'alimentaríamos'::text,'Ojalá no hubiéramos alimentado a los babuinos; ahora están retrasando nuestra reunión de las 10:00.'::text),
(352481,39165,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si seulement on ... les babouins ; maintenant ils retardent notre réunion de 10 h.'::text,'n''avait pas nourri'::text,'ne nourrissait pas'::text,'ne nourrirait pas'::text,'Si seulement on n''avait pas nourri les babouins ; maintenant ils retardent notre réunion de 10 h.'::text),
(352484,39165,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Keşke babunları ...; şimdi saat 10.00''daki toplantımızı geciktiriyorlar.'::text,'beslemeseydik'::text,'beslemesek'::text,'beslemezdik'::text,'Keşke babunları beslemeseydik; şimdi saat 10.00''daki toplantımızı geciktiriyorlar.'::text),
(352485,39165,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bárcsak ... a páviánokat; most késleltetik a 10 órás megbeszélésünket.'::text,'ne etettük volna meg'::text,'ne etetnénk'::text,'ne etetnénk'::text,'Bárcsak ne etettük volna meg a páviánokat; most késleltetik a 10 órás megbeszélésünket.'::text),
(352488,39166,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Fahrer, ... Banane sich die Paviane geschnappt haben, wird sie nie wieder füttern. Ein Albtraum!'::text,'dessen'::text,'der'::text,'welche'::text,'Der Fahrer, dessen Banane sich die Paviane geschnappt haben, wird sie nie wieder füttern. Ein Albtraum!'::text),
(352492,39166,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Водій, ... банан схопили павіани, більше ніколи їх не годуватиме. Жах!'::text,'чий'::text,'який'::text,'що'::text,'Водій, чий банан схопили павіани, більше ніколи їх не годуватиме. Жах!'::text),
(352491,39166,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El conductor, ... plátano agarraron los babuinos, nunca más les dará de comer. ¡Una pesadilla!'::text,'cuyo'::text,'que'::text,'el cual'::text,'El conductor, cuyo plátano agarraron los babuinos, nunca más les dará de comer. ¡Una pesadilla!'::text),
(352490,39166,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le conducteur, ... les babouins ont piqué la banane, ne les nourrira plus jamais. Un cauchemar !'::text,'dont'::text,'qui'::text,'lequel'::text,'Le conducteur, dont les babouins ont piqué la banane, ne les nourrira plus jamais. Un cauchemar !'::text),
(352493,39166,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Muzu babunlar tarafından kapılan ... şoför, onları bir daha asla beslemeyecek. Tam bir kâbus!'::text,''::text,NULL::text,NULL::text,'Muzu babunlar tarafından kapılan şoför, onları bir daha asla beslemeyecek. Tam bir kâbus!'::text),
(352494,39166,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A sofőr, ... banánját a páviánok elkapták, soha többé nem eteti meg őket. Rémálom!'::text,'akinek a'::text,'aki'::text,'ami'::text,'A sofőr, akinek a banánját a páviánok elkapták, soha többé nem eteti meg őket. Rémálom!'::text),
(352497,39167,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Paviane bleiben ruhig, ... niemand versucht, sie zu füttern. Sonst totales Chaos!'::text,'solange'::text,'falls'::text,'es sei denn'::text,'Die Paviane bleiben ruhig, solange niemand versucht, sie zu füttern. Sonst totales Chaos!'::text),
(352501,39167,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Павіани залишатимуться спокійними, ... ніхто не намагатиметься їх годувати. Інакше повний хаос!'::text,'поки'::text,'на випадок, якщо'::text,'хіба що'::text,'Павіани залишатимуться спокійними, поки ніхто не намагатиметься їх годувати. Інакше повний хаос!'::text),
(352500,39167,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Los babuinos se quedarán tranquilos ... nadie intente darles de comer. ¡Si no, caos total!'::text,'siempre que'::text,'por si'::text,'a menos que'::text,'Los babuinos se quedarán tranquilos siempre que nadie intente darles de comer. ¡Si no, caos total!'::text),
(352499,39167,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Les babouins resteront calmes ... personne n''essaie de les nourrir. Sinon, chaos total !'::text,'tant que'::text,'au cas où'::text,'à moins que'::text,'Les babouins resteront calmes tant que personne n''essaie de les nourrir. Sinon, chaos total !'::text),
(352502,39167,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kimse onları beslemeye çalışmadığı ... babunlar sakin kalacak. Yoksa tam bir kaos!'::text,'sürece'::text,'diye'::text,'meğer ki'::text,'Kimse onları beslemeye çalışmadığı sürece babunlar sakin kalacak. Yoksa tam bir kaos!'::text),
(352503,39167,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A páviánok nyugodtak maradnak, ... senki sem próbálja megetetni őket. Különben teljes káosz!'::text,'amíg'::text,'arra az esetre, ha'::text,'hacsak nem'::text,'A páviánok nyugodtak maradnak, amíg senki sem próbálja megetetni őket. Különben teljes káosz!'::text),
(354945,39439,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Als das Kajak den Wasserfall erreichte, ... die Strömung viel schneller geworden.'::text,'war'::text,'ist'::text,'wird'::text,'Als das Kajak den Wasserfall erreichte, war die Strömung viel schneller geworden.'::text),
(354949,39439,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Коли каяк дістався водоспаду, течія ... набагато швидшою.'::text,'стала'::text,'стала'::text,'стає'::text,'Коли каяк дістався водоспаду, течія стала набагато швидшою.'::text),
(354948,39439,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Para cuando el kayak llegó a la cascada, la corriente ... mucho más rápida.'::text,'se había vuelto'::text,'se ha vuelto'::text,'se vuelve'::text,'Para cuando el kayak llegó a la cascada, la corriente se había vuelto mucho más rápida.'::text),
(354947,39439,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Quand le kayak a atteint la cascade, le courant ... beaucoup plus rapide.'::text,'était devenu'::text,'est devenu'::text,'devient'::text,'Quand le kayak a atteint la cascade, le courant était devenu beaucoup plus rapide.'::text),
(354950,39439,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kano şelaleye vardığında akıntı çok daha hızlı ...'::text,'hale gelmişti'::text,'hale geldi'::text,'hale geliyor'::text,'Kano şelaleye vardığında akıntı çok daha hızlı hale gelmişti.'::text),
(354951,39439,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mire a kajak elérte a vízesést, a sodrás sokkal gyorsabb ...'::text,'lett'::text,'lett'::text,'lesz'::text,'Mire a kajak elérte a vízesést, a sodrás sokkal gyorsabb lett.'::text),
(354954,39440,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Morgen um diese Zeit ... die Paddler mit der Strömung desselben Dschungelflusses.'::text,'treiben'::text,'treiben'::text,'treiben'::text,'Morgen um diese Zeit treiben die Paddler mit der Strömung desselben Dschungelflusses.'::text),
(354958,39440,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Завтра в цей час веслярі ... за течією тієї ж річки в джунглях.'::text,'мчатимуть'::text,'помчать'::text,'мчать'::text,'Завтра в цей час веслярі мчатимуть за течією тієї ж річки в джунглях.'::text),
(354957,39440,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mañana a esta hora, los remeros ... con la corriente del mismo río de la selva.'::text,'estarán bajando'::text,'bajarán'::text,'bajan'::text,'Mañana a esta hora, los remeros estarán bajando con la corriente del mismo río de la selva.'::text),
(354956,39440,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Demain à la même heure, les pagayeurs ... au fil du courant de la même rivière de la jungle.'::text,'seront en train de descendre'::text,'descendront'::text,'descendent'::text,'Demain à la même heure, les pagayeurs seront en train de descendre au fil du courant de la même rivière de la jungle.'::text),
(354959,39440,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yarın bu saatlerde kürekçiler aynı orman nehrinin akıntısıyla ...'::text,'süzülüyor olacak'::text,'süzülecek'::text,'süzülüyor'::text,'Yarın bu saatlerde kürekçiler aynı orman nehrinin akıntısıyla süzülüyor olacak.'::text),
(354960,39440,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Holnap ilyenkor az evezősök ugyanannak a dzsungelfolyónak a sodrásával ...'::text,'fognak siklani'::text,'fognak siklani'::text,'siklanak'::text,'Holnap ilyenkor az evezősök ugyanannak a dzsungelfolyónak a sodrásával fognak siklani.'::text),
(354963,39441,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nee Bro, ich ... nie gegen diese krasse Strömung an, die gewinnt jedes Mal.'::text,'kämpfe'::text,'kämpfe'::text,'kämpfe'::text,'Nee Bro, ich kämpfe nie gegen diese krasse Strömung an, die gewinnt jedes Mal.'::text),
(354967,39441,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Не, бро, я ... з цією шаленою течією, вона щоразу виграє.'::text,'ніколи не боротимусь'::text,'ніколи не боротимусь'::text,'ніколи не борюся'::text,'Не, бро, я ніколи не боротимусь з цією шаленою течією, вона щоразу виграє.'::text),
(354966,39441,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nah, bro, yo ... contra esa corriente loca, va a ganar siempre.'::text,'nunca lucharé'::text,'nunca estaré luchando'::text,'nunca estoy luchando'::text,'Nah, bro, yo nunca lucharé contra esa corriente loca, va a ganar siempre.'::text),
(354965,39441,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nan frère, je ... contre ce courant de fou, il va gagner à chaque fois.'::text,'ne lutterai jamais'::text,'ne serai jamais en train de lutter'::text,'ne lutte jamais'::text,'Nan frère, je ne lutterai jamais contre ce courant de fou, il va gagner à chaque fois.'::text),
(354968,39441,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yok kanka, o çılgın akıntıyla ..., her seferinde o kazanır.'::text,'asla savaşmayacağım'::text,'asla savaşıyor olmayacağım'::text,'asla savaşmıyorum'::text,'Yok kanka, o çılgın akıntıyla asla savaşmayacağım, her seferinde o kazanır.'::text),
(354969,39441,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nem, tesó, én ... azzal az őrült sodrással, az mindig nyer.'::text,'soha nem fogok harcolni'::text,'soha nem fogok harcolni'::text,'soha nem harcolok'::text,'Nem, tesó, én soha nem fogok harcolni azzal az őrült sodrással, az mindig nyer.'::text),
(354972,39442,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bro, wenn die Strömung so schnell ..., fährt dein Kajak irgendwie, wohin es will.'::text,'ist'::text,'war'::text,'sein wird'::text,'Bro, wenn die Strömung so schnell ist, fährt dein Kajak irgendwie, wohin es will.'::text),
(354976,39442,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Бро, якщо течія ... така швидка, твій каяк типу пливе, куди хоче.'::text,''::text,'була'::text,'буде'::text,'Бро, якщо течія така швидка, твій каяк типу пливе, куди хоче.'::text),
(354975,39442,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bro, si la corriente ... así de rápida, tu kayak va más o menos adonde quiere.'::text,'es'::text,'era'::text,'será'::text,'Bro, si la corriente es así de rápida, tu kayak va más o menos adonde quiere.'::text),
(354974,39442,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Frère, si le courant ... aussi rapide, ton kayak va un peu où il veut.'::text,'est'::text,'était'::text,'sera'::text,'Frère, si le courant est aussi rapide, ton kayak va un peu où il veut.'::text),
(354977,39442,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, akıntı bu kadar hızlı ..., kanon resmen istediği yere gider.'::text,'olursa'::text,'olsaydı'::text,'olacaksa'::text,'Kanka, akıntı bu kadar hızlı olursa, kanon resmen istediği yere gider.'::text),
(354978,39442,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tesó, ha a sodrás ilyen gyors ..., a kajakod nagyjából oda megy, ahová akar.'::text,''::text,'volt'::text,'lesz'::text,'Tesó, ha a sodrás ilyen gyors, a kajakod nagyjából oda megy, ahová akar.'::text),
(354990,39444,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn der Fluss keine Strömung hätte, ... er ein See, weil Seen sich nicht bewegen.'::text,'wäre'::text,'wird'::text,'ist'::text,'Wenn der Fluss keine Strömung hätte, wäre er ein See, weil Seen sich nicht bewegen.'::text),
(354994,39444,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якби річка не мала течії, вона ... озером, бо озера не рухаються.'::text,'була б'::text,'буде'::text,'є'::text,'Якби річка не мала течії, вона була б озером, бо озера не рухаються.'::text),
(354993,39444,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si el río no tuviera corriente, ... un lago, porque los lagos no se mueven.'::text,'sería'::text,'será'::text,'es'::text,'Si el río no tuviera corriente, sería un lago, porque los lagos no se mueven.'::text),
(354992,39444,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si la rivière n''avait pas de courant, ce ... un lac, parce que les lacs ne bougent pas.'::text,'serait'::text,'sera'::text,'est'::text,'Si la rivière n''avait pas de courant, ce serait un lac, parce que les lacs ne bougent pas.'::text),
(354995,39444,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nehrin akıntısı olmasaydı, bir göl ..., çünkü göller hareket etmez.'::text,'olurdu'::text,'olacak'::text,NULL::text,'Nehrin akıntısı olmasaydı, bir göl olurdu, çünkü göller hareket etmez.'::text),
(354996,39444,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha a folyónak nem lenne sodrása, tó ..., mert a tavak nem mozognak.'::text,'lenne'::text,'lesz'::text,NULL::text,'Ha a folyónak nem lenne sodrása, tó lenne, mert a tavak nem mozognak.'::text),
(354999,39445,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Das Kajak ... von der Strömung über den Wasserfall getragen, wie im Filmmaterial zu sehen ist.'::text,'wurde'::text,'trug'::text,'hat'::text,'Das Kajak wurde von der Strömung über den Wasserfall getragen, wie im Filmmaterial zu sehen ist.'::text),
(355003,39445,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Каяк ... течією через водоспад, як видно на записі.'::text,'був перенесений'::text,'переніс'::text,'переніс'::text,'Каяк був перенесений течією через водоспад, як видно на записі.'::text),
(355002,39445,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El kayak ... por la corriente sobre la cascada, como se observa en las imágenes.'::text,'fue arrastrado'::text,'arrastró'::text,'ha arrastrado'::text,'El kayak fue arrastrado por la corriente sobre la cascada, como se observa en las imágenes.'::text),
(355001,39445,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le kayak ... par le courant par-dessus la cascade, comme on l''observe sur les images.'::text,'a été emporté'::text,'a emporté'::text,'a emporté'::text,'Le kayak a été emporté par le courant par-dessus la cascade, comme on l''observe sur les images.'::text),
(355004,39445,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Görüntülerde gözlemlendiği üzere kano akıntı tarafından şelaleden aşağı ...'::text,'taşındı'::text,'taşıdı'::text,'taşıdı'::text,'Görüntülerde gözlemlendiği üzere kano akıntı tarafından şelaleden aşağı taşındı.'::text),
(355005,39445,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A kajakot ... a sodrás a vízesésen át, ahogy a felvételen megfigyelhető.'::text,'vitte'::text,'vitte'::text,'vitte'::text,'A kajakot vitte a sodrás a vízesésen át, ahogy a felvételen megfigyelhető.'::text),
(355008,39446,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die starke Strömung ... das gelbe Kajak direkt über den Wasserfall.'::text,'trug'::text,'wurde getragen'::text,'tragend'::text,'Die starke Strömung trug das gelbe Kajak direkt über den Wasserfall.'::text),
(355012,39446,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Сильна течія ... жовтий каяк просто через водоспад.'::text,'перенесла'::text,'була перенесена'::text,'несучи'::text,'Сильна течія перенесла жовтий каяк просто через водоспад.'::text),
(355011,39446,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La fuerte corriente ... el kayak amarillo directo por la cascada.'::text,'arrastró'::text,'fue arrastrada'::text,'arrastrando'::text,'La fuerte corriente arrastró el kayak amarillo directo por la cascada.'::text),
(355010,39446,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le courant puissant ... le kayak jaune droit par-dessus la cascade.'::text,'a emporté'::text,'a été emporté'::text,'emportant'::text,'Le courant puissant a emporté le kayak jaune droit par-dessus la cascade.'::text),
(355013,39446,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Güçlü akıntı sarı kanoyu doğrudan şelaleden aşağı ...'::text,'taşıdı'::text,'taşındı'::text,'taşıyarak'::text,'Güçlü akıntı sarı kanoyu doğrudan şelaleden aşağı taşıdı.'::text),
(355014,39446,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Az erős sodrás egyenesen a vízesésen át ... a sárga kajakot.'::text,'vitte'::text,'vitték'::text,'víve'::text,'Az erős sodrás egyenesen a vízesésen át vitte a sárga kajakot.'::text),
(355017,39447,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ziemlich beeindruckend: Du ... Nerven aus Stahl haben, um dieser Strömung über einen Wasserfall zu folgen.'::text,'musst'::text,'kannst nicht'::text,'solltest nicht'::text,'Ziemlich beeindruckend: Du musst Nerven aus Stahl haben, um dieser Strömung über einen Wasserfall zu folgen.'::text),
(355021,39447,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Досить вражає: ти ... мати сталеві нерви, щоб іти за цією течією через водоспад.'::text,'мусиш'::text,'не можеш'::text,'не повинен'::text,'Досить вражає: ти мусиш мати сталеві нерви, щоб іти за цією течією через водоспад.'::text),
(355020,39447,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bastante impresionante: ... tener nervios de acero para seguir esa corriente por una cascada.'::text,'debes de'::text,'no puedes'::text,'no deberías'::text,'Bastante impresionante: debes de tener nervios de acero para seguir esa corriente por una cascada.'::text),
(355019,39447,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Plutôt impressionnant : tu ... avoir des nerfs d''acier pour suivre ce courant par-dessus une cascade.'::text,'dois'::text,'ne peux pas'::text,'ne devrais pas'::text,'Plutôt impressionnant : tu dois avoir des nerfs d''acier pour suivre ce courant par-dessus une cascade.'::text),
(355022,39447,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Epey etkileyici: o akıntıyı şelaleden aşağı takip etmek için çelik gibi sinirlerin ...'::text,'olmalı'::text,'olamaz'::text,'olmamalı'::text,'Epey etkileyici: o akıntıyı şelaleden aşağı takip etmek için çelik gibi sinirlerin olmalı.'::text),
(355023,39447,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elég lenyűgöző: ... acélidegeid, hogy követed azt a sodrást egy vízesésen át.'::text,'biztos vannak'::text,'nem lehetnek'::text,'nem kéne legyenek'::text,'Elég lenyűgöző: biztos vannak acélidegeid, hogy követed azt a sodrást egy vízesésen át.'::text),
(355026,39448,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Respekt, du hast die Linie gewählt, ... die Strömung am schnellsten war, direkt über den Wasserfall.'::text,'wo'::text,'die'::text,'der'::text,'Respekt, du hast die Linie gewählt, wo die Strömung am schnellsten war, direkt über den Wasserfall.'::text),
(355030,39448,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Респект, ти обрав лінію, ... течія була найшвидшою, просто через водоспад.'::text,'де'::text,'яку'::text,'хто'::text,'Респект, ти обрав лінію, де течія була найшвидшою, просто через водоспад.'::text),
(355029,39448,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Respeto, elegiste la línea ... la corriente era más rápida, justo por la cascada.'::text,'donde'::text,'que'::text,'quien'::text,'Respeto, elegiste la línea donde la corriente era más rápida, justo por la cascada.'::text),
(355028,39448,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Respect, tu as choisi la ligne ... le courant était le plus rapide, pile au-dessus de la cascade.'::text,'où'::text,'que'::text,'qui'::text,'Respect, tu as choisi la ligne où le courant était le plus rapide, pile au-dessus de la cascade.'::text),
(355031,39448,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Helal, akıntının en hızlı olduğu ... çizgiyi seçtin, tam şelalenin üstünden.'::text,''::text,NULL::text,NULL::text,'Helal, akıntının en hızlı olduğu çizgiyi seçtin, tam şelalenin üstünden.'::text),
(355032,39448,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Respekt, azt a vonalat választottad, ... a sodrás a leggyorsabb volt, pont a vízesésen át.'::text,'ahol'::text,'amelyet'::text,'aki'::text,'Respekt, azt a vonalat választottad, ahol a sodrás a leggyorsabb volt, pont a vízesésen át.'::text),
(355035,39449,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Guide sagte, die Strömung ... am nächsten Tag wegen des Regens stärker.'::text,'wäre'::text,'wird'::text,'ist'::text,'Der Guide sagte, die Strömung wäre am nächsten Tag wegen des Regens stärker.'::text),
(355039,39449,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Гід сказав, що наступного дня через дощ течія ... сильнішою.'::text,'буде'::text,'буде'::text,'є'::text,'Гід сказав, що наступного дня через дощ течія буде сильнішою.'::text),
(355038,39449,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El guía dijo que la corriente ... más fuerte al día siguiente por la lluvia.'::text,'sería'::text,'será'::text,'es'::text,'El guía dijo que la corriente sería más fuerte al día siguiente por la lluvia.'::text),
(355037,39449,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le guide a dit que le courant ... plus fort le lendemain à cause de la pluie.'::text,'serait'::text,'sera'::text,'est'::text,'Le guide a dit que le courant serait plus fort le lendemain à cause de la pluie.'::text),
(355040,39449,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Rehber, yağmur yüzünden ertesi gün akıntının daha güçlü ... söyledi.'::text,'olacağını'::text,'olacağını'::text,'olduğunu'::text,'Rehber, yağmur yüzünden ertesi gün akıntının daha güçlü olacağını söyledi.'::text),
(355041,39449,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Az idegenvezető azt mondta, hogy az eső miatt másnap erősebb ... a sodrás.'::text,'lesz'::text,'lesz'::text,NULL::text,'Az idegenvezető azt mondta, hogy az eső miatt másnap erősebb lesz a sodrás.'::text),
(362856,40318,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Taucher ... früher, der Kiefer dieses Hais sei schwach, bis sie seine Zähne sahen.'::text,'dachten'::text,'dachten immer'::text,'waren gewohnt zu denken'::text,'Taucher dachten früher, der Kiefer dieses Hais sei schwach, bis sie seine Zähne sahen.'::text),
(362860,40318,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Дайвери ..., що щелепа цієї акули слабка, поки не побачили її зуби.'::text,'колись думали'::text,'бувало, думали'::text,'звикли думати'::text,'Дайвери колись думали, що щелепа цієї акули слабка, поки не побачили її зуби.'::text),
(362859,40318,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Los buceadores ... pensar que la mandíbula de este tiburón era débil, hasta que vieron sus dientes.'::text,'solían'::text,'solían'::text,'estaban acostumbrados a'::text,'Los buceadores solían pensar que la mandíbula de este tiburón era débil, hasta que vieron sus dientes.'::text),
(362858,40318,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Les plongeurs ... que la mâchoire de ce requin était faible, jusqu''à ce qu''ils voient ses dents.'::text,'pensaient autrefois'::text,'pensaient'::text,'avaient l''habitude de penser'::text,'Les plongeurs pensaient autrefois que la mâchoire de ce requin était faible, jusqu''à ce qu''ils voient ses dents.'::text),
(362861,40318,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dalgıçlar, dişlerini görene kadar bu köpekbalığının çenesinin zayıf olduğunu ...'::text,'düşünürdü'::text,'düşünürdü'::text,'düşünmeye alışkındı'::text,'Dalgıçlar, dişlerini görene kadar bu köpekbalığının çenesinin zayıf olduğunu düşünürdü.'::text),
(362862,40318,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A búvárok ..., hogy ennek a cápának gyenge az állkapcsa, amíg meg nem látták a fogait.'::text,'régen azt hitték'::text,'azt hitték'::text,'hozzászoktak ahhoz, hogy azt higgyék'::text,'A búvárok régen azt hitték, hogy ennek a cápának gyenge az állkapcsa, amíg meg nem látták a fogait.'::text),
(362865,40319,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Hai beschloss, seinen Kiefer ... – direkt vor der Kamera. Wirklich tolle Manieren.'::text,'zu öffnen'::text,'öffnend'::text,'öffnen'::text,'Der Hai beschloss, seinen Kiefer zu öffnen – direkt vor der Kamera. Wirklich tolle Manieren.'::text),
(362869,40319,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Акула вирішила ... щелепу просто перед камерою. Справді чудові манери.'::text,'відкрити'::text,'відкривання'::text,'відкрити'::text,'Акула вирішила відкрити щелепу просто перед камерою. Справді чудові манери.'::text),
(362868,40319,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El tiburón decidió ... la mandíbula justo delante de la cámara. Qué modales tan buenos, de verdad.'::text,'abrir'::text,'abriendo'::text,'abre'::text,'El tiburón decidió abrir la mandíbula justo delante de la cámara. Qué modales tan buenos, de verdad.'::text),
(362867,40319,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le requin a décidé ... sa mâchoire juste devant la caméra. Vraiment de bonnes manières.'::text,'d''ouvrir'::text,'ouvrant'::text,'ouvrir'::text,'Le requin a décidé d''ouvrir sa mâchoire juste devant la caméra. Vraiment de bonnes manières.'::text),
(362870,40319,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Köpekbalığı çenesini tam kameranın önünde ... karar verdi. Gerçekten harika görgü kuralları.'::text,'açmaya'::text,'açmayı'::text,'aç'::text,'Köpekbalığı çenesini tam kameranın önünde açmaya karar verdi. Gerçekten harika görgü kuralları.'::text),
(362871,40319,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A cápa úgy döntött, hogy ... az állkapcsát pont a kamera előtt. Igazán remek modor.'::text,'kinyitja'::text,'kinyitás'::text,'kinyit'::text,'A cápa úgy döntött, hogy kinyitja az állkapcsát pont a kamera előtt. Igazán remek modor.'::text),
(362874,40320,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bro, der Kiefer von dem Hai ist schon ziemlich riesig, ...'::text,'oder?'::text,'oder?'::text,'oder?'::text,'Bro, der Kiefer von dem Hai ist schon ziemlich riesig, oder?'::text),
(362878,40320,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Бро, щелепа цієї акули якась величезна, ...'::text,'скажи?'::text,'скажи?'::text,'скажи?'::text,'Бро, щелепа цієї акули якась величезна, скажи?'::text),
(362877,40320,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bro, la mandíbula de ese tiburón es medio enorme, ¿...'::text,'no?'::text,'no?'::text,'no?'::text,'Bro, la mandíbula de ese tiburón es medio enorme, ¿no?'::text),
(362876,40320,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Frère, la mâchoire de ce requin est genre énorme, ...'::text,'hein ?'::text,'hein ?'::text,'hein ?'::text,'Frère, la mâchoire de ce requin est genre énorme, hein ?'::text),
(362879,40320,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, o köpekbalığının çenesi baya kocaman, ...'::text,'değil mi?'::text,'değil mi?'::text,'değil mi?'::text,'Kanka, o köpekbalığının çenesi baya kocaman, değil mi?'::text),
(362880,40320,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tesó, annak a cápának elég hatalmas az állkapcsa, ...'::text,'nem?'::text,'nem?'::text,'nem?'::text,'Tesó, annak a cápának elég hatalmas az állkapcsa, nem?'::text),
(362892,40322,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Laut Tauchbericht ... der Hai 40 Meter auf die Kamera zu, bevor sich sein Kiefer öffnete.'::text,'schwamm'::text,'schwimmt'::text,'schwamm'::text,'Laut Tauchbericht schwamm der Hai 40 Meter auf die Kamera zu, bevor sich sein Kiefer öffnete.'::text),
(362896,40322,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Згідно зі звітом про занурення, акула ... до камери 40 метрів, перш ніж її щелепа відкрилася.'::text,'пливла'::text,'пливе'::text,'пливла'::text,'Згідно зі звітом про занурення, акула пливла до камери 40 метрів, перш ніж її щелепа відкрилася.'::text),
(362895,40322,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Según el informe de buceo, el tiburón ... hacia la cámara durante 40 metros antes de abrir la mandíbula.'::text,'había estado nadando'::text,'ha estado nadando'::text,'estaba nadando'::text,'Según el informe de buceo, el tiburón había estado nadando hacia la cámara durante 40 metros antes de abrir la mandíbula.'::text),
(362894,40322,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Selon le rapport de plongée, le requin ... vers la caméra sur 40 mètres avant que sa mâchoire s''ouvre.'::text,'avait nagé'::text,'a nagé'::text,'nageait'::text,'Selon le rapport de plongée, le requin avait nagé vers la caméra sur 40 mètres avant que sa mâchoire s''ouvre.'::text),
(362897,40322,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dalış raporuna göre köpekbalığı, çenesi açılmadan önce 40 metre boyunca kameraya doğru ...'::text,'yüzmüştü'::text,'yüzüyor'::text,'yüzüyordu'::text,'Dalış raporuna göre köpekbalığı, çenesi açılmadan önce 40 metre boyunca kameraya doğru yüzmüştü.'::text),
(362898,40322,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A merülési jelentés szerint a cápa 40 méteren át ... a kamera felé, mielőtt kinyílt az állkapcsa.'::text,'úszott'::text,'úszik'::text,'úszott'::text,'A merülési jelentés szerint a cápa 40 méteren át úszott a kamera felé, mielőtt kinyílt az állkapcsa.'::text),
(362901,40323,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bis du schreist, ... dieser Kiefer für immer zugeschnappt sein!'::text,'wird'::text,'wird'::text,'schnappt'::text,'Bis du schreist, wird dieser Kiefer für immer zugeschnappt sein!'::text),
(362905,40323,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Поки ти закричиш, ця щелепа вже ... назавжди!'::text,'зімкнеться'::text,'зімкнеться'::text,'змикається'::text,'Поки ти закричиш, ця щелепа вже зімкнеться назавжди!'::text),
(362904,40323,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Para cuando grites, esa mandíbula ya ... para siempre!'::text,'se habrá cerrado'::text,'se cerrará'::text,'se cierra'::text,'¡Para cuando grites, esa mandíbula ya se habrá cerrado para siempre!'::text),
(362903,40323,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le temps que tu cries, cette mâchoire ... pour toujours !'::text,'se sera refermée'::text,'se refermera'::text,'se referme'::text,'Le temps que tu cries, cette mâchoire se sera refermée pour toujours !'::text),
(362906,40323,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sen çığlık atana kadar o çene sonsuza dek ...!'::text,'kapanmış olacak'::text,'kapanacak'::text,'kapanıyor'::text,'Sen çığlık atana kadar o çene sonsuza dek kapanmış olacak!'::text),
(362907,40323,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mire felsikítasz, az az állkapocs örökre ...!'::text,'összecsattan'::text,'össze fog csattanni'::text,'összecsattan'::text,'Mire felsikítasz, az az állkapocs örökre összecsattan!'::text),
(362910,40324,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bis Sonnenuntergang ... dieser Hai schon zehn Stunden lang mit seinem furchterregenden Kiefer in diesen Gewässern gejagt haben!'::text,'wird'::text,'wird'::text,'wird'::text,'Bis Sonnenuntergang wird dieser Hai schon zehn Stunden lang mit seinem furchterregenden Kiefer in diesen Gewässern gejagt haben!'::text),
(362914,40324,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'До заходу сонця ця акула вже десять годин ... в цих водах зі своєю жахливою щелепою!'::text,'полюватиме'::text,'полюватиме'::text,'полюватиме'::text,'До заходу сонця ця акула вже десять годин полюватиме в цих водах зі своєю жахливою щелепою!'::text),
(362913,40324,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Para el atardecer, este tiburón ... en estas aguas con su terrorífica mandíbula durante diez horas!'::text,'habrá estado cazando'::text,'estará cazando'::text,'cazará'::text,'¡Para el atardecer, este tiburón habrá estado cazando en estas aguas con su terrorífica mandíbula durante diez horas!'::text),
(362912,40324,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'D''ici le coucher du soleil, ce requin ... dans ces eaux avec sa mâchoire terrifiante pendant dix heures !'::text,'aura chassé'::text,'chassera'::text,'chassera'::text,'D''ici le coucher du soleil, ce requin aura chassé dans ces eaux avec sa mâchoire terrifiante pendant dix heures !'::text),
(362915,40324,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Gün batımına kadar bu köpekbalığı korkunç çenesiyle on saattir bu sularda ...!'::text,'avlanıyor olacak'::text,'avlanıyor olacak'::text,'avlanacak'::text,'Gün batımına kadar bu köpekbalığı korkunç çenesiyle on saattir bu sularda avlanıyor olacak!'::text),
(362916,40324,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Napnyugtára ez a cápa már tíz órája ... ezekben a vizekben a félelmetes állkapcsával!'::text,'vadászik'::text,'vadászni fog'::text,'vadászni fog'::text,'Napnyugtára ez a cápa már tíz órája vadászik ezekben a vizekben a félelmetes állkapcsával!'::text),
(362928,40326,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hätte die Art keinen so kräftigen Kiefer entwickelt, ... sie heute kein Spitzenprädator.'::text,'wäre'::text,'wäre gewesen'::text,'wird'::text,'Hätte die Art keinen so kräftigen Kiefer entwickelt, wäre sie heute kein Spitzenprädator.'::text),
(362932,40326,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якби в цього виду не розвинулася така потужна щелепа, сьогодні він ... верховним хижаком.'::text,'не був би'::text,'не був би'::text,'не буде'::text,'Якби в цього виду не розвинулася така потужна щелепа, сьогодні він не був би верховним хижаком.'::text),
(362931,40326,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si la especie no hubiera desarrollado una mandíbula tan potente, hoy ... un superdepredador.'::text,'no sería'::text,'no habría sido'::text,'no será'::text,'Si la especie no hubiera desarrollado una mandíbula tan potente, hoy no sería un superdepredador.'::text),
(362930,40326,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si l''espèce n''avait pas développé une mâchoire aussi puissante, elle ... un superprédateur aujourd''hui.'::text,'ne serait pas'::text,'n''aurait pas été'::text,'ne sera pas'::text,'Si l''espèce n''avait pas développé une mâchoire aussi puissante, elle ne serait pas un superprédateur aujourd''hui.'::text),
(362933,40326,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tür bu kadar güçlü bir çene geliştirmemiş olsaydı, bugün bir üst yırtıcı ...'::text,'olmazdı'::text,'olmamış olurdu'::text,'olmayacak'::text,'Tür bu kadar güçlü bir çene geliştirmemiş olsaydı, bugün bir üst yırtıcı olmazdı.'::text),
(362934,40326,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha a faj nem fejlesztett volna ki ilyen erős állkapcsot, ma nem ... csúcsragadozó.'::text,'lenne'::text,'lett volna'::text,'lesz'::text,'Ha a faj nem fejlesztett volna ki ilyen erős állkapcsot, ma nem lenne csúcsragadozó.'::text),
(362937,40327,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Man glaubt, dass der Hai seinen Kiefer nur ..., um den Taucher mit der Kamera zu warnen.'::text,'geöffnet hat'::text,'öffnet'::text,'öffnend'::text,'Man glaubt, dass der Hai seinen Kiefer nur geöffnet hat, um den Taucher mit der Kamera zu warnen.'::text),
(362941,40327,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вважається, що акула ... щелепу лише для того, щоб попередити дайвера з камерою.'::text,'відкрила'::text,'відкриває'::text,'відкриваючи'::text,'Вважається, що акула відкрила щелепу лише для того, щоб попередити дайвера з камерою.'::text),
(362940,40327,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Se cree que el tiburón ... la mandíbula solo para advertir al buzo de la cámara.'::text,'abrió'::text,'abre'::text,'abriendo'::text,'Se cree que el tiburón abrió la mandíbula solo para advertir al buzo de la cámara.'::text),
(362939,40327,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'On pense que le requin ... sa mâchoire seulement pour avertir le plongeur caméraman.'::text,'a ouvert'::text,'ouvre'::text,'ouvrant'::text,'On pense que le requin a ouvert sa mâchoire seulement pour avertir le plongeur caméraman.'::text),
(362942,40327,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Köpekbalığının çenesini yalnızca kameralı dalgıcı uyarmak için ... düşünülüyor.'::text,'açtığı'::text,'açacağı'::text,'açarak'::text,'Köpekbalığının çenesini yalnızca kameralı dalgıcı uyarmak için açtığı düşünülüyor.'::text),
(362943,40327,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Úgy tartják, hogy a cápa csak azért ... ki az állkapcsát, hogy figyelmeztesse a kamerás búvárt.'::text,'nyitotta'::text,'nyitja'::text,'nyitva'::text,'Úgy tartják, hogy a cápa csak azért nyitotta ki az állkapcsát, hogy figyelmeztesse a kamerás búvárt.'::text),
(362946,40328,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Taucher gab zu, Angst ..., als der Hai seinen Kiefer öffnete.'::text,'gehabt zu haben'::text,'zu haben'::text,'hatte'::text,'Der Taucher gab zu, Angst gehabt zu haben, als der Hai seinen Kiefer öffnete.'::text),
(362950,40328,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Дайвер зізнався, що ... наляканий, коли акула відкрила щелепу.'::text,'був'::text,'бути'::text,'був'::text,'Дайвер зізнався, що був наляканий, коли акула відкрила щелепу.'::text),
(362949,40328,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El buzo admitió ... asustado cuando el tiburón abrió la mandíbula.'::text,'haber estado'::text,'estar'::text,'estaba'::text,'El buzo admitió haber estado asustado cuando el tiburón abrió la mandíbula.'::text),
(362948,40328,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le plongeur a admis ... eu peur quand le requin a ouvert sa mâchoire.'::text,'avoir'::text,'avoir'::text,'avait'::text,'Le plongeur a admis avoir eu peur quand le requin a ouvert sa mâchoire.'::text),
(362951,40328,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dalgıç, köpekbalığı çenesini açtığında ... itiraf etti.'::text,'korktuğunu'::text,'korkmayı'::text,'korktu'::text,'Dalgıç, köpekbalığı çenesini açtığında korktuğunu itiraf etti.'::text),
(362952,40328,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A búvár beismerte, hogy ..., amikor a cápa kinyitotta az állkapcsát.'::text,'megijedt'::text,'megijedni'::text,'megijedt'::text,'A búvár beismerte, hogy megijedt, amikor a cápa kinyitotta az állkapcsát.'::text),
(358860,39874,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er ... die Bar sehr fest gehalten haben, weil der Kite sie ihm nie weggerissen hat.'::text,'muss'::text,'hätte'::text,'hätte nicht'::text,'Er muss die Bar sehr fest gehalten haben, weil der Kite sie ihm nie weggerissen hat.'::text),
(358864,39874,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він ... планку дуже міцно, бо кайт жодного разу її не вирвав.'::text,'напевно, тримав'::text,'мав тримати'::text,'не мусив тримати'::text,'Він напевно, тримав планку дуже міцно, бо кайт жодного разу її не вирвав.'::text),
(358863,39874,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Él ... agarrado la barra con mucha fuerza, porque la cometa nunca se la arrancó.'::text,'debió de haber'::text,'debería haber'::text,'no tenía que haber'::text,'Él debió de haber agarrado la barra con mucha fuerza, porque la cometa nunca se la arrancó.'::text),
(358862,39874,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il ... tenir la barre très fort, parce que le kite ne la lui a jamais arrachée.'::text,'a dû'::text,'aurait dû'::text,'n''avait pas besoin de'::text,'Il a dû tenir la barre très fort, parce que le kite ne la lui a jamais arrachée.'::text),
(358865,39874,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Barı çok sıkı ..., çünkü uçurtma onu hiç elinden çekip almadı.'::text,'kavramış olmalı'::text,'kavramalıydı'::text,'kavramasına gerek yoktu'::text,'Barı çok sıkı kavramış olmalı, çünkü uçurtma onu hiç elinden çekip almadı.'::text),
(358866,39874,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nagyon erősen ... a rudat, mert a sárkány soha nem rántotta ki a kezéből.'::text,'markolhatta'::text,'markolnia kellett volna'::text,'nem kellett volna markolnia'::text,'Nagyon erősen markolhatta a rudat, mert a sárkány soha nem rántotta ki a kezéből.'::text),
(358869,39875,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nie zuvor ... eine Bar so fest umklammert, mitten in so einem Chaos!'::text,'hatte er'::text,'er hatte'::text,'hat er'::text,'Nie zuvor hatte er eine Bar so fest umklammert, mitten in so einem Chaos!'::text),
(358873,39875,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ніколи ще він ... планку керування так міцно посеред такого хаосу!'::text,'не стискав'::text,'не стискав'::text,'не стискав'::text,'Ніколи ще він не стискав планку керування так міцно посеред такого хаосу!'::text),
(358872,39875,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Nunca ... una barra de control con tanta fuerza en medio de semejante caos!'::text,'había agarrado'::text,'había agarrado'::text,'agarró'::text,'¡Nunca había agarrado una barra de control con tanta fuerza en medio de semejante caos!'::text),
(358871,39875,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Jamais ... une barre de contrôle aussi fort au milieu d''un tel chaos !'::text,'il n''avait serré'::text,'il n''avait serré'::text,'il n''a serré'::text,'Jamais il n''avait serré une barre de contrôle aussi fort au milieu d''un tel chaos !'::text),
(358874,39875,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Böyle bir kaosun ortasında bir kontrol barını hiç bu kadar sıkı ...!'::text,'kavramamıştı'::text,'kavramamıştı'::text,'kavramadı'::text,'Böyle bir kaosun ortasında bir kontrol barını hiç bu kadar sıkı kavramamıştı!'::text),
(358875,39875,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Soha nem ... még ilyen erősen a kormányrudat ekkora káosz közepén!'::text,'markolta'::text,'markolta'::text,'markolta'::text,'Soha nem markolta még ilyen erősen a kormányrudat ekkora káosz közepén!'::text),
(358878,39876,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nach dieser Katastrophe ließ er die Bar in Gummi ..., um sie besser greifen zu können!'::text,'einwickeln'::text,'einwickeln'::text,'einzuwickeln'::text,'Nach dieser Katastrophe ließ er die Bar in Gummi einwickeln, um sie besser greifen zu können!'::text),
(358882,39876,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Після тієї катастрофи він попросив ... планку гумою, щоб краще її тримати!'::text,'обмотати'::text,'обмотати'::text,'обмотати'::text,'Після тієї катастрофи він попросив обмотати планку гумою, щоб краще її тримати!'::text),
(358881,39876,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Después de ese desastre, mandó ... la barra con goma para agarrarla mejor!'::text,'forrar'::text,'forrar'::text,'a forrar'::text,'¡Después de ese desastre, mandó forrar la barra con goma para agarrarla mejor!'::text),
(358880,39876,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Après ce désastre, il a fait ... la barre de caoutchouc pour mieux la tenir !'::text,'envelopper'::text,'envelopper'::text,'à envelopper'::text,'Après ce désastre, il a fait envelopper la barre de caoutchouc pour mieux la tenir !'::text),
(358883,39876,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'O felaketten sonra barı daha iyi kavramak için lastikle ...!'::text,'kaplattı'::text,'kaplattı'::text,'kaplatmak'::text,'O felaketten sonra barı daha iyi kavramak için lastikle kaplattı!'::text),
(358884,39876,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A katasztrófa után ... a rudat gumival, hogy jobban tudja markolni!'::text,'bevonatta'::text,'bevonatta'::text,'bevonatni'::text,'A katasztrófa után bevonatta a rudat gumival, hogy jobban tudja markolni!'::text),
(358887,39877,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mädel, er hat mir erzählt, er wünschte, er ... die Bar fester gehalten, bevor die Gischt kam.'::text,'hätte'::text,'würde'::text,'hielt'::text,'Mädel, er hat mir erzählt, er wünschte, er hätte die Bar fester gehalten, bevor die Gischt kam.'::text),
(358891,39877,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Подруго, він сказав мені, що шкодує, що не ... планку міцніше, перш ніж накрили бризки.'::text,'стиснув'::text,'стиснув би'::text,'стискав'::text,'Подруго, він сказав мені, що шкодує, що не стиснув планку міцніше, перш ніж накрили бризки.'::text),
(358890,39877,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Amiga, me dijo que ojalá ... la barra más fuerte antes de que le cayera ese chorro de agua.'::text,'hubiera agarrado'::text,'agarraría'::text,'agarrara'::text,'Amiga, me dijo que ojalá hubiera agarrado la barra más fuerte antes de que le cayera ese chorro de agua.'::text),
(358889,39877,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Meuf, il m''a dit qu''il aurait voulu ... la barre plus fort avant que ces embruns arrivent.'::text,'avoir tenu'::text,'tenir'::text,'tenir'::text,'Meuf, il m''a dit qu''il aurait voulu avoir tenu la barre plus fort avant que ces embruns arrivent.'::text),
(358892,39877,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kızım, o su sıçramadan önce keşke barı daha sıkı ... dedi.'::text,'kavrasaydım'::text,'kavrasam'::text,'kavradım'::text,'Kızım, o su sıçramadan önce keşke barı daha sıkı kavrasaydım dedi.'::text),
(358893,39877,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Csajszi, azt mondta, bárcsak erősebben ... a rudat, mielőtt jött az a permet.'::text,'markolta volna'::text,'markolná'::text,'markolta'::text,'Csajszi, azt mondta, bárcsak erősebben markolta volna a rudat, mielőtt jött az a permet.'::text),
(358896,39878,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Rider, ... Hände die Bar um sein Leben umklammerten, war natürlich total entspannt.'::text,'dessen'::text,'der'::text,'welcher'::text,'Der Rider, dessen Hände die Bar um sein Leben umklammerten, war natürlich total entspannt.'::text),
(358900,39878,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Райдер, ... руки вчепилися в планку як у рятівне коло, був, звісно, абсолютно розслаблений.'::text,'чиї'::text,'який'::text,'що'::text,'Райдер, чиї руки вчепилися в планку як у рятівне коло, був, звісно, абсолютно розслаблений.'::text),
(358899,39878,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El rider, ... manos agarraban la barra como si le fuera la vida en ello, estaba totalmente relajado, obviamente.'::text,'cuyas'::text,'que'::text,'el cual'::text,'El rider, cuyas manos agarraban la barra como si le fuera la vida en ello, estaba totalmente relajado, obviamente.'::text),
(358898,39878,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le rider, ... les mains serraient la barre comme si sa vie en dépendait, était totalement détendu, évidemment.'::text,'dont'::text,'qui'::text,'lequel'::text,'Le rider, dont les mains serraient la barre comme si sa vie en dépendait, était totalement détendu, évidemment.'::text),
(358901,39878,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elleri canını dişine takarak barı kavrayan ... sörfçü tamamen rahattı, belli ki.'::text,''::text,NULL::text,NULL::text,'Elleri canını dişine takarak barı kavrayan sörfçü tamamen rahattı, belli ki.'::text),
(358902,39878,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A kiter, ... keze görcsösen markolta a rudat, nyilván teljesen nyugodt volt.'::text,'akinek a'::text,'aki'::text,'ami'::text,'A kiter, akinek a keze görcsösen markolta a rudat, nyilván teljesen nyugodt volt.'::text),
(358914,39880,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er wusste, dass er die Bar 2 Stunden lang ..., also hat er das Morgenmeeting ausgelassen.'::text,'halten würde'::text,'halten wird'::text,'hält'::text,'Er wusste, dass er die Bar 2 Stunden lang halten würde, also hat er das Morgenmeeting ausgelassen.'::text),
(358918,39880,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він знав, що ... планку 2 години, тож пропустив ранкову нараду.'::text,'триматиме'::text,'триматиме'::text,'тримає'::text,'Він знав, що триматиме планку 2 години, тож пропустив ранкову нараду.'::text),
(358917,39880,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sabía que ... la barra durante 2 horas, así que se saltó la reunión de la mañana.'::text,'estaría agarrando'::text,'estará agarrando'::text,'está agarrando'::text,'Sabía que estaría agarrando la barra durante 2 horas, así que se saltó la reunión de la mañana.'::text),
(358916,39880,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il savait qu''il ... la barre pendant 2 heures, alors il a zappé la réunion du matin.'::text,'tiendrait'::text,'tiendra'::text,'tient'::text,'Il savait qu''il tiendrait la barre pendant 2 heures, alors il a zappé la réunion du matin.'::text),
(358919,39880,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Barı 2 saat boyunca ... biliyordu, bu yüzden sabah toplantısını atladı.'::text,'tutacağını'::text,'tutacağını'::text,'tuttuğunu'::text,'Barı 2 saat boyunca tutacağını biliyordu, bu yüzden sabah toplantısını atladı.'::text),
(358920,39880,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tudta, hogy 2 órán át ... a rudat, ezért kihagyta a reggeli megbeszélést.'::text,'fogja markolni'::text,'fogja markolni'::text,'markolja'::text,'Tudta, hogy 2 órán át fogja markolni a rudat, ezért kihagyta a reggeli megbeszélést.'::text),
(358923,39881,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er ... die Bar immer mit beiden Händen, wenn der Kite stark zieht.'::text,'hält'::text,'hält'::text,'hat gehalten'::text,'Er hält die Bar immer mit beiden Händen, wenn der Kite stark zieht.'::text),
(358927,39881,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він завжди ... планку обома руками, коли кайт сильно тягне.'::text,'тримає'::text,'тримає'::text,'тримав'::text,'Він завжди тримає планку обома руками, коли кайт сильно тягне.'::text),
(358926,39881,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Él siempre ... la barra con las dos manos cuando la cometa tira fuerte.'::text,'agarra'::text,'está agarrando'::text,'ha agarrado'::text,'Él siempre agarra la barra con las dos manos cuando la cometa tira fuerte.'::text),
(358925,39881,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il ... toujours la barre à deux mains quand le kite tire fort.'::text,'tient'::text,'tient'::text,'a tenu'::text,'Il tient toujours la barre à deux mains quand le kite tire fort.'::text),
(358928,39881,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Uçurtma sert çektiğinde barı her zaman iki eliyle ...'::text,'kavrar'::text,'kavrıyor'::text,'kavradı'::text,'Uçurtma sert çektiğinde barı her zaman iki eliyle kavrar.'::text),
(358929,39881,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mindig két kézzel ... a rudat, amikor a sárkány erősen húz.'::text,'markolja'::text,'markolja'::text,'markolta'::text,'Mindig két kézzel markolja a rudat, amikor a sárkány erősen húz.'::text),
(358932,39882,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er ... die Bar schon ein paar Sekunden, als plötzlich Gischt die Kamera bedeckte.'::text,'hielt'::text,'hält'::text,'hält'::text,'Er hielt die Bar schon ein paar Sekunden, als plötzlich Gischt die Kamera bedeckte.'::text),
(358936,39882,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він уже кілька секунд ... планку, коли бризки раптом накрили камеру.'::text,'тримав'::text,'тримає'::text,'тримає'::text,'Він уже кілька секунд тримав планку, коли бризки раптом накрили камеру.'::text),
(358935,39882,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Él ... la barra unos segundos cuando el agua de repente cubrió la cámara.'::text,'llevaba agarrando'::text,'lleva agarrando'::text,'agarra'::text,'Él llevaba agarrando la barra unos segundos cuando el agua de repente cubrió la cámara.'::text),
(358934,39882,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il ... la barre depuis quelques secondes quand des embruns ont soudain recouvert la caméra.'::text,'tenait'::text,'tient'::text,'tient'::text,'Il tenait la barre depuis quelques secondes quand des embruns ont soudain recouvert la caméra.'::text),
(358937,39882,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Birden su sıçrayıp kamerayı kapladığında, birkaç saniyedir barı ...'::text,'kavrıyordu'::text,'kavrıyor'::text,'kavrar'::text,'Birden su sıçrayıp kamerayı kapladığında, birkaç saniyedir barı kavrıyordu.'::text),
(358938,39882,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Már néhány másodperce ... a rudat, amikor a permet hirtelen beterítette a kamerát.'::text,'markolta'::text,'markolja'::text,'markolja'::text,'Már néhány másodperce markolta a rudat, amikor a permet hirtelen beterítette a kamerát.'::text),
(358941,39883,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bis zum Sonnenuntergang ... er die Bar mehr als drei Stunden lang gehalten haben.'::text,'wird'::text,'wird'::text,'hält'::text,'Bis zum Sonnenuntergang wird er die Bar mehr als drei Stunden lang gehalten haben.'::text),
(358945,39883,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'До заходу сонця він ... планку вже понад три години.'::text,'триматиме'::text,'триматиме'::text,'тримає'::text,'До заходу сонця він триматиме планку вже понад три години.'::text),
(358944,39883,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Para el atardecer, ... la barra durante más de tres horas.'::text,'habrá estado agarrando'::text,'agarrará'::text,'agarra'::text,'Para el atardecer, habrá estado agarrando la barra durante más de tres horas.'::text),
(358943,39883,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'D''ici le coucher du soleil, il ... la barre pendant plus de trois heures.'::text,'aura tenu'::text,'tiendra'::text,'tient'::text,'D''ici le coucher du soleil, il aura tenu la barre pendant plus de trois heures.'::text),
(358946,39883,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Gün batımına kadar barı üç saatten fazla ...'::text,'kavramış olacak'::text,'kavrayacak'::text,'kavrıyor'::text,'Gün batımına kadar barı üç saatten fazla kavramış olacak.'::text),
(358947,39883,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Napnyugtára már több mint három órája ... a rudat.'::text,'fogja markolni'::text,'fogja markolni'::text,'markolja'::text,'Napnyugtára már több mint három órája fogja markolni a rudat.'::text),
(379956,42218,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Das Individuum ... reglos in den Gurten, als sie ihn freigaben.'::text,'hing'::text,'hing'::text,'hat gehangen'::text,'Das Individuum hing reglos in den Gurten, als sie ihn freigaben.'::text),
(379960,42218,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Індивід ... нерухомо на стропах, коли вони його відпустили.'::text,'висів'::text,'висів'::text,'висів'::text,'Індивід висів нерухомо на стропах, коли вони його відпустили.'::text),
(379959,42218,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El individuo ... inmóvil de las correas cuando lo soltaron.'::text,'colgaba'::text,'colgó'::text,'ha colgado'::text,'El individuo colgaba inmóvil de las correas cuando lo soltaron.'::text),
(379958,42218,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'L''individu ... immobile aux sangles quand elles l''ont lâché.'::text,'était suspendu'::text,'a été suspendu'::text,'a été suspendu'::text,'L''individu était suspendu immobile aux sangles quand elles l''ont lâché.'::text),
(379961,42218,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kayışlar onu bıraktığında birey kayışlarda hareketsiz ...'::text,'asılı duruyordu'::text,'asılı durdu'::text,'asılı durdu'::text,'Kayışlar onu bıraktığında birey kayışlarda hareketsiz asılı duruyordu.'::text),
(379962,42218,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Az egyed mozdulatlanul ... a hevedereken, amikor elengedték.'::text,'lógott'::text,'lógott'::text,'lógott'::text,'Az egyed mozdulatlanul lógott a hevedereken, amikor elengedték.'::text),
(379965,42219,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Du ... seit zehn Minuten darauf, losgelassen zu werden, und ehrlich, du bist immer noch so ruhig.'::text,'wartest'::text,'wartest'::text,'wartest'::text,'Du wartest seit zehn Minuten darauf, losgelassen zu werden, und ehrlich, du bist immer noch so ruhig.'::text),
(379969,42219,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ти вже десять хвилин ..., поки тебе відпустять, і чесно, ти досі такий спокійний.'::text,'чекаєш'::text,'чекаєш'::text,'чекаєш'::text,'Ти вже десять хвилин чекаєш, поки тебе відпустять, і чесно, ти досі такий спокійний.'::text),
(379968,42219,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Llevas diez minutos ... a que te suelten y, sinceramente, sigues tan tranquilo.'::text,'esperando'::text,'estás esperando'::text,'esperas'::text,'Llevas diez minutos esperando a que te suelten y, sinceramente, sigues tan tranquilo.'::text),
(379967,42219,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tu ... d''être lâché depuis dix minutes, et franchement, tu restes tellement calme.'::text,'attends'::text,'attends'::text,'attends'::text,'Tu attends d''être lâché depuis dix minutes, et franchement, tu restes tellement calme.'::text),
(379970,42219,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'On dakikadır bırakılmayı ... ve açıkçası hâlâ çok sakinsin.'::text,'bekliyorsun'::text,'bekliyorsun'::text,'beklersin'::text,'On dakikadır bırakılmayı bekliyorsun ve açıkçası hâlâ çok sakinsin.'::text),
(379971,42219,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Már tíz perce ... arra, hogy elengedjenek, és őszintén, még mindig olyan nyugodt vagy.'::text,'vársz'::text,'vársz'::text,'vársz'::text,'Már tíz perce vársz arra, hogy elengedjenek, és őszintén, még mindig olyan nyugodt vagy.'::text),
(379974,42220,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Gurte ließen dich los, während du so ruhig nach unten ... Smooth, ehrlich.'::text,'schautest'::text,'schautest'::text,'hast geschaut'::text,'Die Gurte ließen dich los, während du so ruhig nach unten schautest Smooth, ehrlich.'::text),
(379978,42220,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Стропи відпустили тебе, поки ти так спокійно ... вниз. Чесно, стильно.'::text,'дивився'::text,'подивився'::text,'подивився'::text,'Стропи відпустили тебе, поки ти так спокійно дивився вниз. Чесно, стильно.'::text),
(379977,42220,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Las correas te soltaron mientras ... hacia abajo tan tranquilo. Con estilo, la verdad.'::text,'mirabas'::text,'miraste'::text,'has mirado'::text,'Las correas te soltaron mientras mirabas hacia abajo tan tranquilo. Con estilo, la verdad.'::text),
(379976,42220,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Les sangles t''ont lâché pendant que tu ... en bas si calmement. Stylé, franchement.'::text,'regardais'::text,'as regardé'::text,'as regardé'::text,'Les sangles t''ont lâché pendant que tu regardais en bas si calmement. Stylé, franchement.'::text),
(379979,42220,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sen öyle sakin sakin aşağı ... kayışlar seni bıraktı. Havalıydı, açıkçası.'::text,'bakarken'::text,'baktın'::text,'baktın'::text,'Sen öyle sakin sakin aşağı bakarken kayışlar seni bıraktı. Havalıydı, açıkçası.'::text),
(379980,42220,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A hevederek elengedtek, miközben olyan nyugodtan ... lefelé. Laza volt, őszintén.'::text,'néztél'::text,'néztél'::text,'néztél'::text,'A hevederek elengedtek, miközben olyan nyugodtan néztél lefelé. Laza volt, őszintén.'::text),
(379983,42221,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ganz ehrlich, diese Gurte ... dich seit Sonnenaufgang dreimal losgelassen, und du lächelst jedes Mal.'::text,'haben'::text,'haben'::text,'ließen'::text,'Ganz ehrlich, diese Gurte haben dich seit Sonnenaufgang dreimal losgelassen, und du lächelst jedes Mal.'::text),
(379987,42221,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Не брехатиму, ці стропи ... тебе тричі від світанку, і ти щоразу усміхаєшся.'::text,'відпустили'::text,'відпускали'::text,'відпустили'::text,'Не брехатиму, ці стропи відпустили тебе тричі від світанку, і ти щоразу усміхаєшся.'::text),
(379986,42221,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'No voy a mentir, esas correas te ... tres veces desde el amanecer, y sonríes cada vez.'::text,'han soltado'::text,'han estado soltando'::text,'soltaron'::text,'No voy a mentir, esas correas te han soltado tres veces desde el amanecer, y sonríes cada vez.'::text),
(379985,42221,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Je vais pas mentir, ces sangles ... trois fois depuis le lever du soleil, et tu souris à chaque fois.'::text,'t''ont lâché'::text,'te lâchent'::text,'t''ont lâché'::text,'Je vais pas mentir, ces sangles t''ont lâché trois fois depuis le lever du soleil, et tu souris à chaque fois.'::text),
(379988,42221,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yalan yok, o kayışlar gün doğumundan beri seni üç kez ... ve sen her seferinde gülümsüyorsun.'::text,'bıraktı'::text,'bırakıp duruyor'::text,'bıraktı'::text,'Yalan yok, o kayışlar gün doğumundan beri seni üç kez bıraktı ve sen her seferinde gülümsüyorsun.'::text),
(379989,42221,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nem hazudok, ezek a hevederek napkelte óta háromszor ... el, és te minden alkalommal mosolyogsz.'::text,'engedtek'::text,'engedtek'::text,'engedtek'::text,'Nem hazudok, ezek a hevederek napkelte óta háromszor engedtek el, és te minden alkalommal mosolyogsz.'::text),
(379992,42222,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Mann ... seine Angst schon lange verloren, bevor die Gurte ihn losließen. Eindeutig ein ruhiger Montag.'::text,'hatte'::text,'hat'::text,'verliert'::text,'Der Mann hatte seine Angst schon lange verloren, bevor die Gurte ihn losließen. Eindeutig ein ruhiger Montag.'::text),
(379996,42222,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Чоловік ... страх задовго до того, як стропи його відпустили. Явно спокійний понеділок.'::text,'втратив'::text,'втратив'::text,'втрачає'::text,'Чоловік втратив страх задовго до того, як стропи його відпустили. Явно спокійний понеділок.'::text),
(379995,42222,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El hombre ... el miedo mucho antes de que las correas lo soltaran. Claramente, un lunes tranquilo.'::text,'había perdido'::text,'ha perdido'::text,'pierde'::text,'El hombre había perdido el miedo mucho antes de que las correas lo soltaran. Claramente, un lunes tranquilo.'::text),
(379994,42222,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'L''homme ... sa peur bien avant que les sangles le lâchent. Clairement un lundi tranquille.'::text,'avait perdu'::text,'a perdu'::text,'perd'::text,'L''homme avait perdu sa peur bien avant que les sangles le lâchent. Clairement un lundi tranquille.'::text),
(379997,42222,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Adam ... korkusunu, kayışlar onu bırakmadan çok önce. Belli ki sakin bir pazartesi.'::text,'kaybetmişti'::text,'kaybetti'::text,'kaybediyor'::text,'Adam kaybetmişti korkusunu, kayışlar onu bırakmadan çok önce. Belli ki sakin bir pazartesi.'::text),
(379998,42222,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A férfi már jóval azelőtt ... a félelmét, hogy a hevederek elengedték. Egyértelműen nyugis hétfő.'::text,'elvesztette'::text,'elvesztette'::text,'elveszíti'::text,'A férfi már jóval azelőtt elvesztette a félelmét, hogy a hevederek elengedték. Egyértelműen nyugis hétfő.'::text),
(380001,42223,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Mann, ... die Gurte losgelassen haben, hat offensichtlich einen entspannten Morgen.'::text,'den'::text,'welchen'::text,'dessen'::text,'Der Mann, den die Gurte losgelassen haben, hat offensichtlich einen entspannten Morgen.'::text),
(380005,42223,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Чоловік, ... відпустили стропи, явно має розслаблений ранок.'::text,'якого'::text,'якого'::text,'чий'::text,'Чоловік, якого відпустили стропи, явно має розслаблений ранок.'::text),
(380004,42223,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El hombre ... soltaron las correas está teniendo claramente una mañana relajante.'::text,'al que'::text,'que'::text,'cuyo'::text,'El hombre al que soltaron las correas está teniendo claramente una mañana relajante.'::text),
(380003,42223,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'L''homme ... les sangles ont lâché passe clairement une matinée relaxante.'::text,'que'::text,'lequel'::text,'dont'::text,'L''homme que les sangles ont lâché passe clairement une matinée relaxante.'::text),
(380006,42223,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kayışların bıraktığı ... adam belli ki rahatlatıcı bir sabah geçiriyor.'::text,''::text,NULL::text,NULL::text,'Kayışların bıraktığı adam belli ki rahatlatıcı bir sabah geçiriyor.'::text),
(380007,42223,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A férfi, ... a hevederek elengedtek, nyilvánvalóan pihentető reggelt tölt.'::text,'akit'::text,'amit'::text,'akinek a'::text,'A férfi, akit a hevederek elengedtek, nyilvánvalóan pihentető reggelt tölt.'::text),
(380010,42224,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er sagte, die Gurte ... ihn bei drei loslassen, und offensichtlich taten sie das auch.'::text,'würden'::text,'werden'::text,'lassen'::text,'Er sagte, die Gurte würden ihn bei drei loslassen, und offensichtlich taten sie das auch.'::text),
(380014,42224,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він сказав, що стропи ... його на рахунок «три», і, очевидно, так і сталося.'::text,'відпустять'::text,'відпустять'::text,'відпускають'::text,'Він сказав, що стропи відпустять його на рахунок «три», і, очевидно, так і сталося.'::text),
(380013,42224,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dijo que las correas lo ... a la de tres, y, obviamente, lo hicieron.'::text,'soltarían'::text,'soltarán'::text,'sueltan'::text,'Dijo que las correas lo soltarían a la de tres, y, obviamente, lo hicieron.'::text),
(380012,42224,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il a dit que les sangles le ... à trois, et évidemment, c''est ce qu''elles ont fait.'::text,'lâcheraient'::text,'lâcheront'::text,'lâchent'::text,'Il a dit que les sangles le lâcheraient à trois, et évidemment, c''est ce qu''elles ont fait.'::text),
(380015,42224,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kayışların onu üç deyince ... söyledi ve belli ki bıraktılar.'::text,'bırakacağını'::text,'bırakacağını'::text,'bıraktığını'::text,'Kayışların onu üç deyince bırakacağını söyledi ve belli ki bıraktılar.'::text),
(380016,42224,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Azt mondta, hogy a hevederek háromra ..., és nyilván így is lett.'::text,'el fogják engedni'::text,'el fogják engedni'::text,'elengedik'::text,'Azt mondta, hogy a hevederek háromra el fogják engedni, és nyilván így is lett.'::text),
(380019,42225,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er ... Höhenangst, aber jetzt lassen ihn die Gurte über den Wolken los.'::text,'hatte früher'::text,'hatte immer'::text,'ist gewohnt'::text,'Er hatte früher Höhenangst, aber jetzt lassen ihn die Gurte über den Wolken los.'::text),
(380023,42225,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він ... боявся висоти, але тепер стропи відпускають його над хмарами.'::text,'колись'::text,'бувало'::text,'звик'::text,'Він колись боявся висоти, але тепер стропи відпускають його над хмарами.'::text),
(380022,42225,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Él ... tener miedo a las alturas, pero ahora las correas lo sueltan sobre las nubes.'::text,'solía'::text,'solía'::text,'está acostumbrado a'::text,'Él solía tener miedo a las alturas, pero ahora las correas lo sueltan sobre las nubes.'::text),
(380021,42225,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il ... peur du vide, mais maintenant les sangles le lâchent au-dessus des nuages.'::text,'avait autrefois'::text,'avait'::text,'a l''habitude d''avoir'::text,'Il avait autrefois peur du vide, mais maintenant les sangles le lâchent au-dessus des nuages.'::text),
(380024,42225,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yükseklikten ..., ama artık kayışlar onu bulutların üstünde bırakıyor.'::text,'eskiden korkardı'::text,'korkardı'::text,'korkmaya alışkın'::text,'Yükseklikten eskiden korkardı, ama artık kayışlar onu bulutların üstünde bırakıyor.'::text),
(380025,42225,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Régen ... a magasságtól, de most a hevederek a felhők fölött engedik el.'::text,'félt'::text,'félt'::text,'hozzászokott, hogy féljen'::text,'Régen félt a magasságtól, de most a hevederek a felhők fölött engedik el.'::text),
(380037,42227,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er ... jetzt schon seit einer Minute in den Gurten und wartet darauf, losgelassen zu werden.'::text,'hängt'::text,'hängt'::text,'hängt'::text,'Er hängt jetzt schon seit einer Minute in den Gurten und wartet darauf, losgelassen zu werden.'::text),
(380041,42227,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він уже хвилину ... на стропах, чекаючи, коли його відпустять.'::text,'висить'::text,'висить'::text,'висить'::text,'Він уже хвилину висить на стропах, чекаючи, коли його відпустять.'::text),
(380040,42227,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Lleva un minuto ... de las correas, esperando a que lo suelten.'::text,'colgado'::text,'está colgado'::text,'cuelga'::text,'Lleva un minuto colgado de las correas, esperando a que lo suelten.'::text),
(380039,42227,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il ... aux sangles depuis une minute, en attendant d''être lâché.'::text,'est suspendu'::text,'est suspendu'::text,'pend'::text,'Il est suspendu aux sangles depuis une minute, en attendant d''être lâché.'::text),
(380042,42227,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bir dakikadır kayışlarda ..., bırakılmayı bekliyor.'::text,'asılı duruyor'::text,'asılı duruyor'::text,'asılı durur'::text,'Bir dakikadır kayışlarda asılı duruyor, bırakılmayı bekliyor.'::text),
(380043,42227,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Már egy perce ... a hevedereken, és várja, hogy elengedjék.'::text,'lóg'::text,'lóg'::text,'lóg'::text,'Már egy perce lóg a hevedereken, és várja, hogy elengedjék.'::text),
(375141,41683,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dieser Vogel ... schon den ganzen Tag zu diesem furchterregenden Mast, verzweifelt, um seine Küken zu füttern!'::text,'fliegt'::text,'fliegt'::text,'fliegt'::text,'Dieser Vogel fliegt schon den ganzen Tag zu diesem furchterregenden Mast, verzweifelt, um seine Küken zu füttern!'::text),
(375145,41683,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Цей птах цілий день ... до того жахливого стовпа, відчайдушно прагнучи нагодувати пташенят!'::text,'літає'::text,'летить'::text,'літає'::text,'Цей птах цілий день літає до того жахливого стовпа, відчайдушно прагнучи нагодувати пташенят!'::text)
) v(id, eid, lang, n_intro_text, n_correct_answer, n_distractor_1, n_distractor_2, n_full_sentence, o_intro_text, o_correct_answer, o_distractor_1, o_distractor_2, o_full_sentence)
where l.id = v.id and l.exercise_id = v.eid and l.language_code = v.lang and l.intro_text is not distinct from v.o_intro_text and l.correct_answer is not distinct from v.o_correct_answer and l.distractor_1 is not distinct from v.o_distractor_1 and l.distractor_2 is not distinct from v.o_distractor_2 and l.full_sentence is not distinct from v.o_full_sentence
returning l.id;
