(363841,40427,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якщо прийде приплив, цей крихітний пляж ... під лагуною. Бездоганне планування.'::text,'зникне'::text,'зник би'::text,'зник'::text,'Якщо прийде приплив, цей крихітний пляж зникне під лагуною. Бездоганне планування.'::text),
