(363839,40427,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si la marée monte, cette minuscule plage ... sous le lagon. Organisation impeccable.'::text,'disparaîtra'::text,'disparaîtrait'::text,'a disparu'::text,'Si la marée monte, cette minuscule plage disparaîtra sous le lagon. Organisation impeccable.'::text),
(363842,40427,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Gelgit yükselirse bu minik plaj ... lagünün altında. Kusursuz planlama.'::text,'kaybolacak'::text,'kaybolurdu'::text,'kayboldu'::text,'Gelgit yükselirse bu minik plaj kaybolacak lagünün altında. Kusursuz planlama.'::text),
